               cs7 = gdx(p)*gix(p)
               cs8 = &
                  gu(p)*(-1.0_wp/3.0_wp*blend_k*cs0 + gds(p)*(5.0_wp*gfp(p, 0)*gsp(p, 4) + gfp(p, &
                  1)*gsp(p, 5)))
               cs9 = cs8*gix(p)
               cs10 = &
                  cs1*(-2.0_wp/3.0_wp*blend_k*cs3 + gds(p)*(10.0_wp*cs2*gsp(p, 9) + 2.0_wp*gfp(p, &
                  0)*gfp(p, 1)*gsp(p, 10)))
               cs11 = cs10*gix(p)
               cs12 = &
                  cs4*(-blend_k*cs6 + gds(p)*(3.0_wp*cs2*gfp(p, 1)*gsp(p, 15) + 15.0_wp*cs5*gsp(p, &
                  14)))
               cs13 = cs12*gix(p)
               acc(p, 1) = acc(p, 1) + (cs0*gu(p))
               acc(p, 2) = acc(p, 2) + (cs1*cs3)
               acc(p, 3) = acc(p, 3) + (cs4*cs6)
               acc(p, 5) = acc(p, 5) + (cs7*cs8)
               acc(p, 6) = acc(p, 6) + (cs9*gdy(p))
               acc(p, 7) = acc(p, 7) + (cs9*gdz(p))
               acc(p, 8) = acc(p, 8) + (cs10*cs7)
               acc(p, 9) = acc(p, 9) + (cs11*gdy(p))
               acc(p, 10) = acc(p, 10) + (cs11*gdz(p))
               acc(p, 11) = acc(p, 11) + (cs12*cs7)
               acc(p, 12) = acc(p, 12) + (cs13*gdy(p))
               acc(p, 13) = acc(p, 13) + (cs13*gdz(p))
            end do
            if (include_q) then
               do p = 1, np
                  cs0 = (gu(p)*sqrt(gu(p)))
                  cs1 = (gfp(p, 0)*sqrt(gfp(p, 0)))
                  cs2 = cs1*gsh(p, 7)
                  cs3 = &
                     cs0*gix(p)*(-1.0_wp/2.0_wp*blend_k*cs2 + gds(p)*((15.0_wp/2.0_wp)*cs1*gsh(p, &
                     6) + (3.0_wp/2.0_wp)*sqrt(gfp(p, 0))*gfp(p, 1)*gsh(p, 7)))
                  acc(p, 4) = acc(p, 4) + (cs0*cs2)
                  acc(p, 14) = acc(p, 14) + (cs3*gdx(p))
                  acc(p, 15) = acc(p, 15) + (cs3*gdy(p))
                  acc(p, 16) = acc(p, 16) + (cs3*gdz(p))
               end do
            end if
         end if
      end do

      ps0(:, 1) = acc(1:np, 1)
      ps0(:, 2) = acc(1:np, 2)
      ps0(:, 3) = acc(1:np, 3)
      ps0(:, 4) = acc(1:np, 4)
      ps1(:, 1, 1) = acc(1:np, 5)
      ps1(:, 2, 1) = acc(1:np, 6)
      ps1(:, 3, 1) = acc(1:np, 7)
      ps1(:, 1, 2) = acc(1:np, 8)
      ps1(:, 2, 2) = acc(1:np, 9)
      ps1(:, 3, 2) = acc(1:np, 10)
      ps1(:, 1, 3) = acc(1:np, 11)
      ps1(:, 2, 3) = acc(1:np, 12)
      ps1(:, 3, 3) = acc(1:np, 13)
      ps1(:, 1, 4) = acc(1:np, 14)
      ps1(:, 2, 4) = acc(1:np, 15)
      ps1(:, 3, 4) = acc(1:np, 16)

   end subroutine svdw_strip_powersums_o1

   pure module subroutine svdw_strip_lift_o1(np, blend_k, s_1, s_2, s_3, ps0, ps1, lsf0, lsf1_r)
      !> Live points in the strip, 1..32
      integer, intent(in) :: np
      !> Blending sharpness k of u = exp(-(k/3) d)
      real(wp), intent(in) :: blend_k
      !> One-body blending weight blend_1b
      real(wp), intent(in) :: s_1
      !> Two-body blending weight blend_2b
      real(wp), intent(in) :: s_2
      !> Three-body blending weight blend_3b
      real(wp), intent(in) :: s_3
      !> Order-0 power sums of the strip, point-first; last index the kind (1 = p1, 2 = p2, 3 = p3,
      !> 4 = q)
      real(wp), intent(in) :: ps0(np, nkind)
      !> Order-1 power sums of the strip, point-first; middle index the Cartesian component; last
      !> index the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps1(np, 3, nkind)
      !> Level-set value S = -log(Z)/blend_k
      real(wp), intent(out) :: lsf0(np)
      !> Spatial gradient dS/dr
      real(wp), intent(out) :: lsf1_r(3, np)

      !> Strip width of this order
      integer, parameter :: nps = svdw_strip_width(1)
      !> Assembled Z per point and its reciprocal
      real(wp) :: zz(nps), izz(nps)
      !> Packed results, point-first
      real(wp) :: o1(nps, 3)
      !> Common subexpressions of one point
      real(wp) :: cs0, cs1, cs2, cs3, cs4
      !> Point index
      integer :: p

      if (np < 1 .or. np > nps) error stop &
         "svdw_strip_lift_o1: np outside 1..strip width"

      do p = 1, np
         zz(p) = &
            (1.0_wp/6.0_wp)*(ps0(p, 1)*ps0(p, 1)*ps0(p, 1))*s_3 - 1.0_wp/2.0_wp*ps0(p, 1)*ps0(p, &
            2)*s_3 + ps0(p, 3)*s_1 - 1.0_wp/2.0_wp*ps0(p, 3)*s_2 + (1.0_wp/3.0_wp)*ps0(p, 3)*s_3 + &
            (1.0_wp/2.0_wp)*(ps0(p, 4)*ps0(p, 4))*s_2
         izz(p) = 1.0_wp/zz(p)
      end do
      ! libm log: kept out of the vectorized loops
      do p = 1, np
         lsf0(p) = -log(zz(p))/blend_k
      end do

      do p = 1, np
         cs0 = ps0(p, 4)*s_2
         cs1 = (1.0_wp/2.0_wp)*ps0(p, 1)*s_3
         cs2 = s_1 - 1.0_wp/2.0_wp*s_2 + (1.0_wp/3.0_wp)*s_3
         cs3 = (1.0_wp/6.0_wp)*s_3*(3.0_wp*(ps0(p, 1)*ps0(p, 1)) - 3.0_wp*ps0(p, 2))
         cs4 = izz(p)/blend_k
         o1(p, 1) = -cs4*(cs0*ps1(p, 1, 4) - cs1*ps1(p, 1, 2) + cs2*ps1(p, 1, 3) + cs3*ps1(p, 1, 1))
         o1(p, 2) = -cs4*(cs0*ps1(p, 2, 4) - cs1*ps1(p, 2, 2) + cs2*ps1(p, 2, 3) + cs3*ps1(p, 2, 1))
         o1(p, 3) = -cs4*(cs0*ps1(p, 3, 4) - cs1*ps1(p, 3, 2) + cs2*ps1(p, 3, 3) + cs3*ps1(p, 3, 1))
      end do

      do p = 1, np
         lsf1_r(1, p) = o1(p, 1)
         lsf1_r(2, p) = o1(p, 2)
         lsf1_r(3, p) = o1(p, 3)
      end do

   end subroutine svdw_strip_lift_o1

   pure module subroutine svdw_strip_powersums_o2(np, points, nat, centers, radii, bound_sq, blend_k, &
                                           include_q, fade_start, fade_width, ps0, ps1, ps2, &
                                           n_zero, cache_x, cache_inv_x, cache_u)
      !> Live points in the strip, 1..32
      integer, intent(in) :: np
      !> Strip points, point-last
      real(wp), intent(in) :: points(3, np)
      !> Atoms in the shared list
      integer, intent(in) :: nat
      !> Atom centers of the shared list
      real(wp), intent(in) :: centers(3, nat)
      !> Atom radii R_a
      real(wp), intent(in) :: radii(nat)
      !> Squared screening reach per atom, the gate's `cand_screen` row
      real(wp), intent(in) :: bound_sq(nat)
      !> Blending sharpness k of u = exp(-(k/3) d)
      real(wp), intent(in) :: blend_k
      !> Accumulate the kind-4 (`q`) power sums; pass `blend_2b /= 0`
      logical, intent(in) :: include_q
      !> Fade onset X_on in d_A; huge(0.0_wp) for no fade
      real(wp), intent(in) :: fade_start
      !> Fade band width Delta in d_A, finite and > 0
      real(wp), intent(in) :: fade_width
      !> Order-0 power sums of the strip, point-first; last index the kind (1 = p1, 2 = p2, 3 = p3,
      !> 4 = q)
      real(wp), intent(out) :: ps0(np, nkind)
      !> Order-1 power sums of the strip, point-first; middle index the Cartesian component; last
      !> index the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(out) :: ps1(np, 3, nkind)
      !> Order-2 power sums of the strip, point-first; middle index the packed slot of the sorted
      !> rank-2 tuple; last index the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(out) :: ps2(np, 6, nkind)
      !> Point-atom pairs at zero distance whose geometry was evaluated; nonzero means the sums are
      !> not finite
      integer, intent(out) :: n_zero
      !> Distance ||r_p - R_A|| per point and atom (optional)
      real(wp), optional, intent(out) :: cache_x(np, nat)
      !> Reciprocal distance per point and atom (optional)
      real(wp), optional, intent(out) :: cache_inv_x(np, nat)
      !> Gate-masked unfaded screening factor u_A per point and atom (optional)
      real(wp), optional, intent(out) :: cache_u(np, nat)

      !> Strip width of this order
      integer, parameter :: nps = svdw_strip_width(2)
      !> Accumulated columns, one per orbit representative and kind
      integer, parameter :: nacc = 40
      !> Point-first copy of the strip
      real(wp) :: px(nps), py(nps), pz(nps)
      !> Geometry of one atom against the strip, point-first
      real(wp) :: gdx(nps), gdy(nps), gdz(nps), gx(nps), gix(nps), gu(nps)
      !> Accumulators
      real(wp) :: acc(nps, nacc)
      !> Strip bounding box
      real(wp) :: lo(3), hi(3)
      !> Atom data, box distances and hoisted constants
      real(wp) :: cx, cy, cz, ra, bsq, ex, ey, ez, dnear, dfar, bk3, band_end, inv_delta
      !> Point geometry and inline-exp scalars
      real(wp) :: dx, dy, dz, r2, x, arg, ekf, er, ep, u
      !> Gate compare and fade of one atom against the strip, point-first
      real(wp) :: gr2(nps), gfs(nps), gds(nps), gfp(nps, 0:2)
      !> Integer and half-integer powers of the fade variable, point-first
      real(wp) :: gsp(nps, 15), gsh(nps, 0:15)
      !> Fade scalars
      real(wp) :: sr, fs, ft, fsq
      !> Common subexpressions of one point-atom pair
      real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11, cs12, cs13, cs14
      real(wp) :: cs15, cs16, cs17, cs18, cs19, cs20, cs21, cs22, cs23, cs24, cs25, cs26, cs27, cs28
      real(wp) :: cs29, cs30, cs31, cs32, cs33, cs34, cs35, cs36, cs37, cs38, cs39, cs40, cs41, cs42
      real(wp) :: cs43
      !> Point and atom indices
      integer :: p, a
      !> Atom beyond the band for the whole strip; geometry cache requested
      logical :: skip, want_cache

      if (np < 1 .or. np > nps) error stop &
         "svdw_strip_powersums_o2: np outside 1..strip width"
      if (.not. fade_width > 0.0_wp) error stop &
         "svdw_strip_powersums_o2: fade_width must be positive"
      if (nat > 0) then
         if (blend_k*maxval(radii)/3.0_wp > exp_arg_max) error stop &
            "svdw_strip_powersums_o2: exp argument bound exceeded"
      end if
      want_cache = present(cache_x) .or. present(cache_inv_x) .or. present(cache_u)

      do p = 1, np
         px(p) = points(1, p)
         py(p) = points(2, p)
         pz(p) = points(3, p)
      end do
      lo(1) = minval(px(1:np))
      lo(2) = minval(py(1:np))
      lo(3) = minval(pz(1:np))
      hi(1) = maxval(px(1:np))
      hi(2) = maxval(py(1:np))
      hi(3) = maxval(pz(1:np))
      bk3 = -blend_k/3.0_wp
      band_end = fade_start + fade_width
      inv_delta = 1.0_wp/fade_width
      acc(1:np, :) = 0.0_wp
      n_zero = 0

      do a = 1, nat
         cx = centers(1, a)
         cy = centers(2, a)
         cz = centers(3, a)
         ra = radii(a)
         bsq = bound_sq(a)

         ! Nearest and farthest box point, as signed sphere distances
         ex = max(lo(1) - cx, 0.0_wp, cx - hi(1))
         ey = max(lo(2) - cy, 0.0_wp, cy - hi(2))
         ez = max(lo(3) - cz, 0.0_wp, cz - hi(3))
         dnear = sqrt(ex*ex + ey*ey + ez*ez) - ra
         ex = max(abs(cx - lo(1)), abs(cx - hi(1)))
         ey = max(abs(cy - lo(2)), abs(cy - hi(2)))
         ez = max(abs(cz - lo(3)), abs(cz - hi(3)))
         dfar = sqrt(ex*ex + ey*ey + ez*ez) - ra
         skip = dnear >= band_end
         if (skip .and. .not. want_cache) cycle

         do p = 1, np
            dx = px(p) - cx
            dy = py(p) - cy
            dz = pz(p) - cz
            r2 = dx*dx + dy*dy + dz*dz
            x = sqrt(r2)
            arg = max(bk3*(x - ra), exp_arg_min)
            ekf = anint(arg*exp_inv_ln2)
            er = arg - ekf*exp_ln2_hi
            er = er - ekf*exp_ln2_lo
            ep = &
               exp_q0 + er*(exp_q1 + er*(exp_q2 + er*(exp_q3 + er*(exp_q4 + er*(exp_q5 + &
               er*(exp_q6 + er*(exp_q7 + er*(exp_q8 + er*(exp_q9 + er*(exp_q10))))))))))
            u = (1.0_wp + (er + er*er*ep))*transfer(ishft(int(ekf, int64) + 1023_int64, 52), 1.0_wp)
            gdx(p) = dx
            gdy(p) = dy
            gdz(p) = dz
            gx(p) = x
            gix(p) = 1.0_wp/x
            gu(p) = u
            gr2(p) = r2
         end do
         ! Hard screening: the gate's own squared compare; a separate loop, as a
         ! select on the exp result lets the compiler sink the exp into a branch
         do p = 1, np
            gu(p) = merge(gu(p), 0.0_wp, gr2(p) <= bsq)
         end do
         n_zero = n_zero + count(gr2(1:np) == 0.0_wp)
         if (present(cache_x)) cache_x(:, a) = gx(1:np)
         if (present(cache_inv_x)) cache_inv_x(:, a) = gix(1:np)
         if (present(cache_u)) cache_u(:, a) = gu(1:np)
         if (skip) cycle

         if (dfar <= fade_start) then
            ! Plateau for the whole strip: plain atom function
            do p = 1, np
               cs0 = (gu(p)*gu(p))
               cs1 = (gu(p)*gu(p)*gu(p))
               cs2 = blend_k*gix(p)
               cs3 = cs2*gdx(p)
               cs4 = (1.0_wp/3.0_wp)*gu(p)
               cs5 = cs2*cs4
               cs6 = (2.0_wp/3.0_wp)*cs0
               cs7 = cs2*cs6
               cs8 = blend_k*cs1
               cs9 = cs8*gix(p)
               cs10 = (gdx(p)*gdx(p))
               cs11 = blend_k*gx(p)
               cs12 = (1.0_wp/3.0_wp)*cs11
               cs13 = -(gx(p)*gx(p))
               cs14 = cs10 + cs13
               cs15 = (gix(p)*gix(p)*gix(p))
               cs16 = blend_k*cs15
               cs17 = cs16*cs4
               cs18 = gdx(p)*gdy(p)
               cs19 = cs17*(cs12 + 1.0_wp)
               cs20 = cs19*gdz(p)
               cs21 = (gdy(p)*gdy(p))
               cs22 = cs13 + cs21
               cs23 = (gdz(p)*gdz(p))
               cs24 = cs13 + cs23
               cs25 = (2.0_wp/3.0_wp)*cs11
               cs26 = cs16*cs6
               cs27 = cs26*(cs25 + 1.0_wp)
               cs28 = cs27*gdz(p)
               cs29 = cs15*cs8
               cs30 = cs29*(cs11 + 1.0_wp)
               cs31 = cs30*gdz(p)
               acc(p, 1) = acc(p, 1) + (gu(p))
               acc(p, 2) = acc(p, 2) + (cs0)
               acc(p, 3) = acc(p, 3) + (cs1)
               acc(p, 5) = acc(p, 5) + (-cs3*cs4)
               acc(p, 6) = acc(p, 6) + (-cs5*gdy(p))
               acc(p, 7) = acc(p, 7) + (-cs5*gdz(p))
               acc(p, 8) = acc(p, 8) + (-cs3*cs6)
               acc(p, 9) = acc(p, 9) + (-cs7*gdy(p))
               acc(p, 10) = acc(p, 10) + (-cs7*gdz(p))
               acc(p, 11) = acc(p, 11) + (-cs9*gdx(p))
               acc(p, 12) = acc(p, 12) + (-cs9*gdy(p))
               acc(p, 13) = acc(p, 13) + (-cs9*gdz(p))
               acc(p, 17) = acc(p, 17) + (cs17*(cs10*cs12 + cs14))
               acc(p, 18) = acc(p, 18) + (cs18*cs19)
               acc(p, 19) = acc(p, 19) + (cs20*gdx(p))
               acc(p, 20) = acc(p, 20) + (cs17*(cs12*cs21 + cs22))
               acc(p, 21) = acc(p, 21) + (cs20*gdy(p))
               acc(p, 22) = acc(p, 22) + (cs17*(cs12*cs23 + cs24))
               acc(p, 23) = acc(p, 23) + (cs26*(cs10*cs25 + cs14))
               acc(p, 24) = acc(p, 24) + (cs18*cs27)
               acc(p, 25) = acc(p, 25) + (cs28*gdx(p))
               acc(p, 26) = acc(p, 26) + (cs26*(cs21*cs25 + cs22))
               acc(p, 27) = acc(p, 27) + (cs28*gdy(p))
               acc(p, 28) = acc(p, 28) + (cs26*(cs23*cs25 + cs24))
               acc(p, 29) = acc(p, 29) + (cs29*(cs10*cs11 + cs14))
               acc(p, 30) = acc(p, 30) + (cs18*cs30)
               acc(p, 31) = acc(p, 31) + (cs31*gdx(p))
               acc(p, 32) = acc(p, 32) + (cs29*(cs11*cs21 + cs22))
               acc(p, 33) = acc(p, 33) + (cs31*gdy(p))
               acc(p, 34) = acc(p, 34) + (cs29*(cs11*cs23 + cs24))
            end do
            if (include_q) then
               do p = 1, np
                  cs0 = (gu(p)*sqrt(gu(p)))
                  cs1 = (1.0_wp/2.0_wp)*blend_k
                  cs2 = cs0*cs1
                  cs3 = cs2*gix(p)
                  cs4 = (gdx(p)*gdx(p))
                  cs5 = -(gx(p)*gx(p))
                  cs6 = cs1*gx(p)
                  cs7 = cs2*(gix(p)*gix(p)*gix(p))
                  cs8 = cs6 + 1.0_wp
                  cs9 = cs7*cs8*gdx(p)
                  cs10 = (gdy(p)*gdy(p))
                  cs11 = (gdz(p)*gdz(p))
                  acc(p, 4) = acc(p, 4) + (cs0)
                  acc(p, 14) = acc(p, 14) + (-cs3*gdx(p))
                  acc(p, 15) = acc(p, 15) + (-cs3*gdy(p))
                  acc(p, 16) = acc(p, 16) + (-cs3*gdz(p))
                  acc(p, 35) = acc(p, 35) + (cs7*(cs4*cs6 + cs4 + cs5))
                  acc(p, 36) = acc(p, 36) + (cs9*gdy(p))
                  acc(p, 37) = acc(p, 37) + (cs9*gdz(p))
                  acc(p, 38) = acc(p, 38) + (cs7*(cs10*cs6 + cs10 + cs5))
                  acc(p, 39) = acc(p, 39) + (cs7*cs8*gdy(p)*gdz(p))
                  acc(p, 40) = acc(p, 40) + (cs7*(cs11*cs6 + cs11 + cs5))
               end do
            end if
         else
            ! Strip meets the band: faded atom function
            do p = 1, np
               sr = (band_end - (gx(p) - ra))*inv_delta
               fs = min(max(sr, 0.0_wp), 1.0_wp)
               ft = min(max((gx(p) - ra - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
               gfs(p) = fs
               gds(p) = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
               gfp(p, 0) = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
               gfp(p, 1) = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
               gfp(p, 2) = ft*(840.0_wp*ft + 210.0_wp) + 30.0_wp
               gsp(p, 1) = fs
               gsp(p, 2) = gsp(p, 1)*fs
               gsp(p, 3) = gsp(p, 2)*fs
               gsp(p, 4) = gsp(p, 3)*fs
               gsp(p, 5) = gsp(p, 4)*fs
               gsp(p, 6) = gsp(p, 5)*fs
               gsp(p, 7) = gsp(p, 6)*fs
               gsp(p, 8) = gsp(p, 7)*fs
               gsp(p, 9) = gsp(p, 8)*fs
               gsp(p, 10) = gsp(p, 9)*fs
               gsp(p, 11) = gsp(p, 10)*fs
               gsp(p, 12) = gsp(p, 11)*fs
               gsp(p, 13) = gsp(p, 12)*fs
               gsp(p, 14) = gsp(p, 13)*fs
               gsp(p, 15) = gsp(p, 14)*fs
               fsq = sqrt(fs)
               gsh(p, 5) = gsp(p, 5)*fsq
               gsh(p, 6) = gsp(p, 6)*fsq
               gsh(p, 7) = gsp(p, 7)*fsq
            end do
            do p = 1, np
               cs0 = gfp(p, 0)*gsp(p, 5)
               cs1 = (gu(p)*gu(p))
               cs2 = (gfp(p, 0)*gfp(p, 0))
               cs3 = cs2*gsp(p, 10)
               cs4 = (gu(p)*gu(p)*gu(p))
               cs5 = (gfp(p, 0)*gfp(p, 0)*gfp(p, 0))
               cs6 = cs5*gsp(p, 15)
               cs7 = 5.0_wp*gfp(p, 0)*gsp(p, 4) + gfp(p, 1)*gsp(p, 5)
               cs8 = gu(p)*(-1.0_wp/3.0_wp*blend_k*cs0 + cs7*gds(p))
               cs9 = cs8*gix(p)
               cs10 = (2.0_wp/3.0_wp)*blend_k
               cs11 = 10.0_wp*cs2*gsp(p, 9) + 2.0_wp*gfp(p, 0)*gfp(p, 1)*gsp(p, 10)
               cs12 = cs1*(-cs10*cs3 + cs11*gds(p))
               cs13 = cs12*gix(p)
               cs14 = 3.0_wp*cs2*gfp(p, 1)*gsp(p, 15) + 15.0_wp*cs5*gsp(p, 14)
               cs15 = cs4*(-blend_k*cs6 + cs14*gds(p))
               cs16 = cs15*gix(p)
               cs17 = (gdx(p)*gdx(p))
               cs18 = (gix(p)*gix(p)*gix(p))
               cs19 = cs18*cs8
               cs20 = (gix(p)*gix(p))
               cs21 = cs17*cs20
               cs22 = (blend_k*blend_k)
               cs23 = (gds(p)*gds(p))
               cs24 = 20.0_wp*gfp(p, 0)
               cs25 = gfp(p, 1)*gfs(p)
               cs26 = &
                  (1.0_wp/9.0_wp)*cs0*cs22 - cs10*cs7*gds(p) + cs23*gsp(p, 3)*(cs24 + 10.0_wp*cs25 &
                  + gfp(p, 2)*gsp(p, 2))
               cs27 = cs26*gu(p)
               cs28 = gdx(p)*gdy(p)
               cs29 = gdx(p)*gdz(p)
               cs30 = (gdy(p)*gdy(p))
               cs31 = cs20*cs27
               cs32 = gdy(p)*gdz(p)
               cs33 = (gdz(p)*gdz(p))
               cs34 = cs12*cs18
               cs35 = (gfp(p, 1)*gfp(p, 1))
               cs36 = gfp(p, 0)*gfp(p, 2)
               cs37 = &
                  -4.0_wp/3.0_wp*blend_k*cs11*gds(p) + (4.0_wp/9.0_wp)*cs22*cs3 + &
                  2.0_wp*cs23*gsp(p, 8)*(45.0_wp*cs2 + cs24*cs25 + gsp(p, 2)*(cs35 + cs36))
               cs38 = cs1*cs37
               cs39 = cs20*cs38
               cs40 = cs15*cs18
               cs41 = &
                  -2.0_wp*blend_k*cs14*gds(p) + cs22*cs6 + 3.0_wp*cs23*gfp(p, 0)*gsp(p, &
                  13)*(70.0_wp*cs2 + 30.0_wp*cs25*gfp(p, 0) + gsp(p, 2)*(2.0_wp*cs35 + cs36))
               cs42 = cs4*cs41
               cs43 = cs20*cs42
               acc(p, 1) = acc(p, 1) + (cs0*gu(p))
               acc(p, 2) = acc(p, 2) + (cs1*cs3)
               acc(p, 3) = acc(p, 3) + (cs4*cs6)
               acc(p, 5) = acc(p, 5) + (cs9*gdx(p))
               acc(p, 6) = acc(p, 6) + (cs9*gdy(p))
               acc(p, 7) = acc(p, 7) + (cs9*gdz(p))
               acc(p, 8) = acc(p, 8) + (cs13*gdx(p))
               acc(p, 9) = acc(p, 9) + (cs13*gdy(p))
               acc(p, 10) = acc(p, 10) + (cs13*gdz(p))
               acc(p, 11) = acc(p, 11) + (cs16*gdx(p))
               acc(p, 12) = acc(p, 12) + (cs16*gdy(p))
               acc(p, 13) = acc(p, 13) + (cs16*gdz(p))
               acc(p, 17) = acc(p, 17) + (-cs17*cs19 + cs21*cs27 + cs9)
               acc(p, 18) = acc(p, 18) + (-cs19*cs28 + cs20*cs26*gdx(p)*gdy(p)*gu(p))
               acc(p, 19) = acc(p, 19) + (-cs19*cs29 + cs20*cs26*gdx(p)*gdz(p)*gu(p))
               acc(p, 20) = acc(p, 20) + (-cs19*cs30 + cs30*cs31 + cs9)
               acc(p, 21) = acc(p, 21) + (-cs19*cs32 + cs20*cs26*gdy(p)*gdz(p)*gu(p))
               acc(p, 22) = acc(p, 22) + (-cs19*cs33 + cs31*cs33 + cs9)
               acc(p, 23) = acc(p, 23) + (cs13 - cs17*cs34 + cs21*cs38)
               acc(p, 24) = acc(p, 24) + (cs1*cs20*cs37*gdx(p)*gdy(p) - cs28*cs34)
               acc(p, 25) = acc(p, 25) + (cs1*cs20*cs37*gdx(p)*gdz(p) - cs29*cs34)
               acc(p, 26) = acc(p, 26) + (cs13 - cs30*cs34 + cs30*cs39)
               acc(p, 27) = acc(p, 27) + (cs1*cs20*cs37*gdy(p)*gdz(p) - cs32*cs34)
               acc(p, 28) = acc(p, 28) + (cs13 - cs33*cs34 + cs33*cs39)
               acc(p, 29) = acc(p, 29) + (cs16 - cs17*cs40 + cs21*cs42)
               acc(p, 30) = acc(p, 30) + (cs20*cs4*cs41*gdx(p)*gdy(p) - cs28*cs40)
               acc(p, 31) = acc(p, 31) + (cs20*cs4*cs41*gdx(p)*gdz(p) - cs29*cs40)
               acc(p, 32) = acc(p, 32) + (cs16 - cs30*cs40 + cs30*cs43)
               acc(p, 33) = acc(p, 33) + (cs20*cs4*cs41*gdy(p)*gdz(p) - cs32*cs40)
               acc(p, 34) = acc(p, 34) + (cs16 - cs33*cs40 + cs33*cs43)
            end do
            if (include_q) then
               do p = 1, np
                  cs0 = (gu(p)*sqrt(gu(p)))
                  cs1 = (gfp(p, 0)*sqrt(gfp(p, 0)))
                  cs2 = cs1*gsh(p, 7)
                  cs3 = sqrt(gfp(p, 0))
                  cs4 = cs3*gfp(p, 1)
                  cs5 = (15.0_wp/2.0_wp)*cs1*gsh(p, 6) + (3.0_wp/2.0_wp)*cs4*gsh(p, 7)
                  cs6 = cs0*(-1.0_wp/2.0_wp*blend_k*cs2 + cs5*gds(p))
                  cs7 = cs6*gix(p)
                  cs8 = (gdx(p)*gdx(p))
                  cs9 = cs6*(gix(p)*gix(p)*gix(p))
                  cs10 = (gix(p)*gix(p))
                  cs11 = &
                     (1.0_wp/4.0_wp)*(blend_k*blend_k)*cs2 - blend_k*cs5*gds(p) + &
                     (3.0_wp/4.0_wp)*(gds(p)*gds(p))*gsh(p, 5)*(65.0_wp*cs1 + 30.0_wp*cs4*gfs(p) + &
                     gsp(p, 2)*(2.0_wp*cs3*gfp(p, 2) + (gfp(p, 1)*gfp(p, 1))/cs3))
                  cs12 = cs0*cs10*cs11
                  cs13 = (gdy(p)*gdy(p))
                  cs14 = (gdz(p)*gdz(p))
                  acc(p, 4) = acc(p, 4) + (cs0*cs2)
                  acc(p, 14) = acc(p, 14) + (cs7*gdx(p))
                  acc(p, 15) = acc(p, 15) + (cs7*gdy(p))
                  acc(p, 16) = acc(p, 16) + (cs7*gdz(p))
                  acc(p, 35) = acc(p, 35) + (cs12*cs8 + cs7 - cs8*cs9)
                  acc(p, 36) = acc(p, 36) + (cs0*cs10*cs11*gdx(p)*gdy(p) - cs9*gdx(p)*gdy(p))
                  acc(p, 37) = acc(p, 37) + (cs0*cs10*cs11*gdx(p)*gdz(p) - cs9*gdx(p)*gdz(p))
                  acc(p, 38) = acc(p, 38) + (cs12*cs13 - cs13*cs9 + cs7)
                  acc(p, 39) = acc(p, 39) + (cs0*cs10*cs11*gdy(p)*gdz(p) - cs9*gdy(p)*gdz(p))
                  acc(p, 40) = acc(p, 40) + (cs12*cs14 - cs14*cs9 + cs7)
               end do
            end if
         end if
      end do

      ps0(:, 1) = acc(1:np, 1)
      ps0(:, 2) = acc(1:np, 2)
      ps0(:, 3) = acc(1:np, 3)
      ps0(:, 4) = acc(1:np, 4)
      ps1(:, 1, 1) = acc(1:np, 5)
      ps1(:, 2, 1) = acc(1:np, 6)
      ps1(:, 3, 1) = acc(1:np, 7)
      ps1(:, 1, 2) = acc(1:np, 8)
      ps1(:, 2, 2) = acc(1:np, 9)
      ps1(:, 3, 2) = acc(1:np, 10)
      ps1(:, 1, 3) = acc(1:np, 11)
      ps1(:, 2, 3) = acc(1:np, 12)
      ps1(:, 3, 3) = acc(1:np, 13)
      ps1(:, 1, 4) = acc(1:np, 14)
      ps1(:, 2, 4) = acc(1:np, 15)
      ps1(:, 3, 4) = acc(1:np, 16)
      ps2(:, 1, 1) = acc(1:np, 17)
      ps2(:, 2, 1) = acc(1:np, 18)
      ps2(:, 4, 1) = acc(1:np, 19)
      ps2(:, 3, 1) = acc(1:np, 20)
      ps2(:, 5, 1) = acc(1:np, 21)
      ps2(:, 6, 1) = acc(1:np, 22)
      ps2(:, 1, 2) = acc(1:np, 23)
      ps2(:, 2, 2) = acc(1:np, 24)
      ps2(:, 4, 2) = acc(1:np, 25)
      ps2(:, 3, 2) = acc(1:np, 26)
      ps2(:, 5, 2) = acc(1:np, 27)
      ps2(:, 6, 2) = acc(1:np, 28)
      ps2(:, 1, 3) = acc(1:np, 29)
      ps2(:, 2, 3) = acc(1:np, 30)
      ps2(:, 4, 3) = acc(1:np, 31)
      ps2(:, 3, 3) = acc(1:np, 32)
      ps2(:, 5, 3) = acc(1:np, 33)
      ps2(:, 6, 3) = acc(1:np, 34)
      ps2(:, 1, 4) = acc(1:np, 35)
      ps2(:, 2, 4) = acc(1:np, 36)
      ps2(:, 4, 4) = acc(1:np, 37)
      ps2(:, 3, 4) = acc(1:np, 38)
      ps2(:, 5, 4) = acc(1:np, 39)
      ps2(:, 6, 4) = acc(1:np, 40)

   end subroutine svdw_strip_powersums_o2

   pure module subroutine svdw_strip_lift_o2(np, blend_k, s_1, s_2, s_3, ps0, ps1, ps2, lsf0, lsf1_r, &
                                      lsf2_rr)
      !> Live points in the strip, 1..32
      integer, intent(in) :: np
      !> Blending sharpness k of u = exp(-(k/3) d)
      real(wp), intent(in) :: blend_k
      !> One-body blending weight blend_1b
      real(wp), intent(in) :: s_1
      !> Two-body blending weight blend_2b
      real(wp), intent(in) :: s_2
      !> Three-body blending weight blend_3b
      real(wp), intent(in) :: s_3
      !> Order-0 power sums of the strip, point-first; last index the kind (1 = p1, 2 = p2, 3 = p3,
      !> 4 = q)
      real(wp), intent(in) :: ps0(np, nkind)
      !> Order-1 power sums of the strip, point-first; middle index the Cartesian component; last
      !> index the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps1(np, 3, nkind)
      !> Order-2 power sums of the strip, point-first; middle index the packed slot of the sorted
      !> rank-2 tuple; last index the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps2(np, 6, nkind)
      !> Level-set value S = -log(Z)/blend_k
      real(wp), intent(out) :: lsf0(np)
      !> Spatial gradient dS/dr
      real(wp), intent(out) :: lsf1_r(3, np)
      !> Spatial Hessian, packed (6)
      real(wp), intent(out) :: lsf2_rr(6, np)

      !> Strip width of this order
      integer, parameter :: nps = svdw_strip_width(2)
      !> Assembled Z per point and its reciprocal
      real(wp) :: zz(nps), izz(nps)
      !> Packed results, point-first
      real(wp) :: o1(nps, 3), o2(nps, 6)
      !> Common subexpressions of one point
      real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11, cs12, cs13, cs14
      real(wp) :: cs15, cs16, cs17, cs18, cs19, cs20
      !> Point index
      integer :: p

      if (np < 1 .or. np > nps) error stop &
         "svdw_strip_lift_o2: np outside 1..strip width"

      do p = 1, np
         zz(p) = &
            (1.0_wp/6.0_wp)*(ps0(p, 1)*ps0(p, 1)*ps0(p, 1))*s_3 - 1.0_wp/2.0_wp*ps0(p, 1)*ps0(p, &
            2)*s_3 + ps0(p, 3)*s_1 - 1.0_wp/2.0_wp*ps0(p, 3)*s_2 + (1.0_wp/3.0_wp)*ps0(p, 3)*s_3 + &
            (1.0_wp/2.0_wp)*(ps0(p, 4)*ps0(p, 4))*s_2
         izz(p) = 1.0_wp/zz(p)
      end do
      ! libm log: kept out of the vectorized loops
      do p = 1, np
         lsf0(p) = -log(zz(p))/blend_k
      end do

      do p = 1, np
         cs0 = ps0(p, 4)*s_2
         cs1 = (1.0_wp/2.0_wp)*s_3
         cs2 = cs1*ps1(p, 1, 2)
         cs3 = s_1 - 1.0_wp/2.0_wp*s_2 + (1.0_wp/3.0_wp)*s_3
         cs4 = (1.0_wp/6.0_wp)*s_3*(3.0_wp*(ps0(p, 1)*ps0(p, 1)) - 3.0_wp*ps0(p, 2))
         cs5 = cs0*ps1(p, 1, 4) - cs2*ps0(p, 1) + cs3*ps1(p, 1, 3) + cs4*ps1(p, 1, 1)
         cs6 = 1.0_wp/blend_k
         cs7 = cs6*izz(p)
         cs8 = cs1*ps1(p, 2, 2)
         cs9 = cs0*ps1(p, 2, 4) + cs3*ps1(p, 2, 3) + cs4*ps1(p, 2, 1) - cs8*ps0(p, 1)
         cs10 = cs1*ps1(p, 3, 2)
         cs11 = cs0*ps1(p, 3, 4) - cs10*ps0(p, 1) + cs3*ps1(p, 3, 3) + cs4*ps1(p, 3, 1)
         cs12 = cs0*cs7
         cs13 = cs7*s_2
         cs14 = cs3*cs7
         cs15 = ps0(p, 1)*s_3
         cs16 = cs7*(cs15*ps1(p, 1, 1) - cs2)
         cs17 = cs4*cs7
         cs18 = (izz(p)*izz(p))
         cs19 = cs13*ps1(p, 1, 4)
         cs20 = cs7*(cs15*ps1(p, 2, 1) - cs8)
         o1(p, 1) = -cs5*cs7
         o1(p, 2) = -cs7*cs9
         o1(p, 3) = -cs11*cs7
         o2(p, 1) = &
            -cs12*ps2(p, 1, 4) - cs13*(ps1(p, 1, 4)*ps1(p, 1, 4)) - cs14*ps2(p, 1, 3) - &
            cs16*ps1(p, 1, 1) - cs17*ps2(p, 1, 1) + cs18*(cs5*cs5)*cs6 + &
            (1.0_wp/2.0_wp)*cs6*izz(p)*ps0(p, 1)*ps2(p, 1, 2)*s_3 + &
            (1.0_wp/2.0_wp)*cs6*izz(p)*ps1(p, 1, 1)*ps1(p, 1, 2)*s_3
         o2(p, 2) = &
            -cs12*ps2(p, 2, 4) - cs14*ps2(p, 2, 3) - cs16*ps1(p, 2, 1) - cs17*ps2(p, 2, 1) + &
            cs18*cs5*cs6*cs9 - cs19*ps1(p, 2, 4) + (1.0_wp/2.0_wp)*cs6*izz(p)*ps0(p, 1)*ps2(p, 2, &
            2)*s_3 + (1.0_wp/2.0_wp)*cs6*izz(p)*ps1(p, 1, 1)*ps1(p, 2, 2)*s_3
         o2(p, 4) = &
            cs11*cs18*cs5*cs6 - cs12*ps2(p, 4, 4) - cs14*ps2(p, 4, 3) - cs16*ps1(p, 3, 1) - &
            cs17*ps2(p, 4, 1) - cs19*ps1(p, 3, 4) + (1.0_wp/2.0_wp)*cs6*izz(p)*ps0(p, 1)*ps2(p, 4, &
            2)*s_3 + (1.0_wp/2.0_wp)*cs6*izz(p)*ps1(p, 1, 1)*ps1(p, 3, 2)*s_3
         o2(p, 3) = &
            -cs12*ps2(p, 3, 4) - cs13*(ps1(p, 2, 4)*ps1(p, 2, 4)) - cs14*ps2(p, 3, 3) - &
            cs17*ps2(p, 3, 1) + cs18*cs6*(cs9*cs9) - cs20*ps1(p, 2, 1) + &
            (1.0_wp/2.0_wp)*cs6*izz(p)*ps0(p, 1)*ps2(p, 3, 2)*s_3 + &
            (1.0_wp/2.0_wp)*cs6*izz(p)*ps1(p, 2, 1)*ps1(p, 2, 2)*s_3
         o2(p, 5) = &
            cs11*cs18*cs6*cs9 - cs12*ps2(p, 5, 4) - cs13*ps1(p, 2, 4)*ps1(p, 3, 4) - cs14*ps2(p, &
            5, 3) - cs17*ps2(p, 5, 1) - cs20*ps1(p, 3, 1) + (1.0_wp/2.0_wp)*cs6*izz(p)*ps0(p, &
            1)*ps2(p, 5, 2)*s_3 + (1.0_wp/2.0_wp)*cs6*izz(p)*ps1(p, 2, 1)*ps1(p, 3, 2)*s_3
         o2(p, 6) = &
            (cs11*cs11)*cs18*cs6 - cs12*ps2(p, 6, 4) - cs13*(ps1(p, 3, 4)*ps1(p, 3, 4)) - &
            cs14*ps2(p, 6, 3) - cs17*ps2(p, 6, 1) + (1.0_wp/2.0_wp)*cs6*izz(p)*ps0(p, 1)*ps2(p, 6, &
            2)*s_3 + (1.0_wp/2.0_wp)*cs6*izz(p)*ps1(p, 3, 1)*ps1(p, 3, 2)*s_3 - cs7*ps1(p, 3, &
            1)*(-cs10 + cs15*ps1(p, 3, 1))
      end do

      do p = 1, np
         lsf1_r(1, p) = o1(p, 1)
         lsf1_r(2, p) = o1(p, 2)
         lsf1_r(3, p) = o1(p, 3)
         lsf2_rr(1, p) = o2(p, 1)
         lsf2_rr(2, p) = o2(p, 2)
         lsf2_rr(3, p) = o2(p, 3)
         lsf2_rr(4, p) = o2(p, 4)
         lsf2_rr(5, p) = o2(p, 5)
         lsf2_rr(6, p) = o2(p, 6)
      end do

   end subroutine svdw_strip_lift_o2

   pure module subroutine svdw_strip_powersums_o3(np, points, nat, centers, radii, bound_sq, blend_k, &
                                           include_q, fade_start, fade_width, ps0, ps1, ps2, ps3, &
                                           n_zero, cache_x, cache_inv_x, cache_u)
      !> Live points in the strip, 1..16
      integer, intent(in) :: np
      !> Strip points, point-last
      real(wp), intent(in) :: points(3, np)
      !> Atoms in the shared list
      integer, intent(in) :: nat
      !> Atom centers of the shared list
      real(wp), intent(in) :: centers(3, nat)
      !> Atom radii R_a
      real(wp), intent(in) :: radii(nat)
      !> Squared screening reach per atom, the gate's `cand_screen` row
      real(wp), intent(in) :: bound_sq(nat)
      !> Blending sharpness k of u = exp(-(k/3) d)
      real(wp), intent(in) :: blend_k
      !> Accumulate the kind-4 (`q`) power sums; pass `blend_2b /= 0`
      logical, intent(in) :: include_q
      !> Fade onset X_on in d_A; huge(0.0_wp) for no fade
      real(wp), intent(in) :: fade_start
      !> Fade band width Delta in d_A, finite and > 0
      real(wp), intent(in) :: fade_width
      !> Order-0 power sums of the strip, point-first; last index the kind (1 = p1, 2 = p2, 3 = p3,
      !> 4 = q)
      real(wp), intent(out) :: ps0(np, nkind)
      !> Order-1 power sums of the strip, point-first; middle index the Cartesian component; last
      !> index the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(out) :: ps1(np, 3, nkind)
      !> Order-2 power sums of the strip, point-first; middle index the packed slot of the sorted
      !> rank-2 tuple; last index the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(out) :: ps2(np, 6, nkind)
      !> Order-3 power sums of the strip, point-first; middle index the packed slot of the sorted
      !> rank-3 tuple; last index the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(out) :: ps3(np, 10, nkind)
      !> Point-atom pairs at zero distance whose geometry was evaluated; nonzero means the sums are
      !> not finite
      integer, intent(out) :: n_zero
      !> Distance ||r_p - R_A|| per point and atom (optional)
      real(wp), optional, intent(out) :: cache_x(np, nat)
      !> Reciprocal distance per point and atom (optional)
      real(wp), optional, intent(out) :: cache_inv_x(np, nat)
      !> Gate-masked unfaded screening factor u_A per point and atom (optional)
      real(wp), optional, intent(out) :: cache_u(np, nat)

      !> Strip width of this order
      integer, parameter :: nps = svdw_strip_width(3)
      !> Accumulated columns, one per orbit representative and kind
      integer, parameter :: nacc = 80
      !> Point-first copy of the strip
      real(wp) :: px(nps), py(nps), pz(nps)
      !> Geometry of one atom against the strip, point-first
      real(wp) :: gdx(nps), gdy(nps), gdz(nps), gx(nps), gix(nps), gu(nps)
      !> Accumulators
      real(wp) :: acc(nps, nacc)
      !> Strip bounding box
      real(wp) :: lo(3), hi(3)
      !> Atom data, box distances and hoisted constants
      real(wp) :: cx, cy, cz, ra, bsq, ex, ey, ez, dnear, dfar, bk3, band_end, inv_delta
      !> Point geometry and inline-exp scalars
      real(wp) :: dx, dy, dz, r2, x, arg, ekf, er, ep, u
      !> Gate compare and fade of one atom against the strip, point-first
      real(wp) :: gr2(nps), gfs(nps), gds(nps), gfp(nps, 0:3)
      !> Integer and half-integer powers of the fade variable, point-first
      real(wp) :: gsp(nps, 15), gsh(nps, 0:15)
      !> Fade scalars
      real(wp) :: sr, fs, ft, fsq
      !> Common subexpressions of one point-atom pair
      real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11, cs12, cs13, cs14
      real(wp) :: cs15, cs16, cs17, cs18, cs19, cs20, cs21, cs22, cs23, cs24, cs25, cs26, cs27, cs28
      real(wp) :: cs29, cs30, cs31, cs32, cs33, cs34, cs35, cs36, cs37, cs38, cs39, cs40, cs41, cs42
      real(wp) :: cs43, cs44, cs45, cs46, cs47, cs48, cs49, cs50, cs51, cs52, cs53, cs54, cs55, cs56
      real(wp) :: cs57, cs58, cs59, cs60, cs61, cs62, cs63, cs64, cs65, cs66, cs67, cs68, cs69, cs70
      real(wp) :: cs71, cs72, cs73, cs74, cs75, cs76, cs77, cs78, cs79, cs80, cs81, cs82, cs83, cs84
      real(wp) :: cs85, cs86, cs87, cs88, cs89, cs90, cs91, cs92, cs93, cs94, cs95, cs96, cs97, cs98
      real(wp) :: cs99, cs100, cs101, cs102, cs103, cs104, cs105, cs106, cs107, cs108, cs109, cs110
      real(wp) :: cs111, cs112, cs113, cs114, cs115, cs116
      !> Point and atom indices
      integer :: p, a
      !> Atom beyond the band for the whole strip; geometry cache requested
      logical :: skip, want_cache

      if (np < 1 .or. np > nps) error stop &
         "svdw_strip_powersums_o3: np outside 1..strip width"
      if (.not. fade_width > 0.0_wp) error stop &
         "svdw_strip_powersums_o3: fade_width must be positive"
      if (nat > 0) then
         if (blend_k*maxval(radii)/3.0_wp > exp_arg_max) error stop &
            "svdw_strip_powersums_o3: exp argument bound exceeded"
      end if
      want_cache = present(cache_x) .or. present(cache_inv_x) .or. present(cache_u)

      do p = 1, np
         px(p) = points(1, p)
         py(p) = points(2, p)
         pz(p) = points(3, p)
      end do
      lo(1) = minval(px(1:np))
      lo(2) = minval(py(1:np))
      lo(3) = minval(pz(1:np))
      hi(1) = maxval(px(1:np))
      hi(2) = maxval(py(1:np))
      hi(3) = maxval(pz(1:np))
      bk3 = -blend_k/3.0_wp
      band_end = fade_start + fade_width
      inv_delta = 1.0_wp/fade_width
      acc(1:np, :) = 0.0_wp
      n_zero = 0

      do a = 1, nat
         cx = centers(1, a)
         cy = centers(2, a)
         cz = centers(3, a)
         ra = radii(a)
         bsq = bound_sq(a)

         ! Nearest and farthest box point, as signed sphere distances
         ex = max(lo(1) - cx, 0.0_wp, cx - hi(1))
         ey = max(lo(2) - cy, 0.0_wp, cy - hi(2))
         ez = max(lo(3) - cz, 0.0_wp, cz - hi(3))
         dnear = sqrt(ex*ex + ey*ey + ez*ez) - ra
         ex = max(abs(cx - lo(1)), abs(cx - hi(1)))
         ey = max(abs(cy - lo(2)), abs(cy - hi(2)))
         ez = max(abs(cz - lo(3)), abs(cz - hi(3)))
         dfar = sqrt(ex*ex + ey*ey + ez*ez) - ra
         skip = dnear >= band_end
         if (skip .and. .not. want_cache) cycle

         do p = 1, np
            dx = px(p) - cx
            dy = py(p) - cy
            dz = pz(p) - cz
            r2 = dx*dx + dy*dy + dz*dz
            x = sqrt(r2)
            arg = max(bk3*(x - ra), exp_arg_min)
            ekf = anint(arg*exp_inv_ln2)
            er = arg - ekf*exp_ln2_hi
            er = er - ekf*exp_ln2_lo
            ep = &
               exp_q0 + er*(exp_q1 + er*(exp_q2 + er*(exp_q3 + er*(exp_q4 + er*(exp_q5 + &
               er*(exp_q6 + er*(exp_q7 + er*(exp_q8 + er*(exp_q9 + er*(exp_q10))))))))))
            u = (1.0_wp + (er + er*er*ep))*transfer(ishft(int(ekf, int64) + 1023_int64, 52), 1.0_wp)
            gdx(p) = dx
            gdy(p) = dy
            gdz(p) = dz
            gx(p) = x
            gix(p) = 1.0_wp/x
            gu(p) = u
            gr2(p) = r2
         end do
         ! Hard screening: the gate's own squared compare; a separate loop, as a
         ! select on the exp result lets the compiler sink the exp into a branch
         do p = 1, np
            gu(p) = merge(gu(p), 0.0_wp, gr2(p) <= bsq)
         end do
         n_zero = n_zero + count(gr2(1:np) == 0.0_wp)
         if (present(cache_x)) cache_x(:, a) = gx(1:np)
         if (present(cache_inv_x)) cache_inv_x(:, a) = gix(1:np)
         if (present(cache_u)) cache_u(:, a) = gu(1:np)
         if (skip) cycle

         if (dfar <= fade_start) then
            ! Plateau for the whole strip: plain atom function
            do p = 1, np
               cs0 = (gu(p)*gu(p))
               cs1 = (gu(p)*gu(p)*gu(p))
               cs2 = blend_k*gix(p)
               cs3 = cs2*gdx(p)
               cs4 = (1.0_wp/3.0_wp)*gu(p)
               cs5 = cs2*cs4
               cs6 = (2.0_wp/3.0_wp)*cs0
               cs7 = cs2*cs6
               cs8 = blend_k*cs1
               cs9 = cs8*gix(p)
               cs10 = (gdx(p)*gdx(p))
               cs11 = blend_k*gx(p)
               cs12 = (1.0_wp/3.0_wp)*cs11
               cs13 = (gx(p)*gx(p))
               cs14 = -cs13
               cs15 = cs10 + cs14
               cs16 = (gix(p)*gix(p)*gix(p))
               cs17 = blend_k*cs16
               cs18 = cs17*cs4
               cs19 = gdx(p)*gdy(p)
               cs20 = cs18*(cs12 + 1.0_wp)
               cs21 = cs20*gdz(p)
               cs22 = (gdy(p)*gdy(p))
               cs23 = cs14 + cs22
               cs24 = (gdz(p)*gdz(p))
               cs25 = cs14 + cs24
               cs26 = (2.0_wp/3.0_wp)*cs11
               cs27 = cs17*cs6
               cs28 = cs27*(cs26 + 1.0_wp)
               cs29 = cs28*gdz(p)
               cs30 = cs10*cs11
               cs31 = cs16*cs8
               cs32 = cs31*(cs11 + 1.0_wp)
               cs33 = cs32*gdz(p)
               cs34 = cs11*cs22
               cs35 = cs11*cs24
               cs36 = (gx(p)*gx(p)*gx(p))
               cs37 = -blend_k*cs36
               cs38 = (blend_k*blend_k)
               cs39 = cs10*cs38
               cs40 = (1.0_wp/9.0_wp)*cs39
               cs41 = 3.0_wp*cs10
               cs42 = cs30 + cs41
               cs43 = (gix(p)*gix(p)*gix(p)*gix(p)*gix(p))
               cs44 = blend_k*cs43
               cs45 = cs4*cs44
               cs46 = cs45*gdx(p)
               cs47 = -1.0_wp/3.0_wp*blend_k*cs36
               cs48 = cs45*(cs13*(1.0_wp - cs40) - cs42 - cs47)
               cs49 = cs22*cs38
               cs50 = (1.0_wp/9.0_wp)*cs49
               cs51 = 3.0_wp*cs22
               cs52 = cs34 + cs51
               cs53 = cs13*(1.0_wp - cs50) - cs47 - cs52
               cs54 = cs13*cs38
               cs55 = cs45*gdz(p)
               cs56 = cs24*cs38
               cs57 = (1.0_wp/9.0_wp)*cs56
               cs58 = 3.0_wp*cs24
               cs59 = cs35 + cs58
               cs60 = cs13*(1.0_wp - cs57) - cs47 - cs59
               cs61 = cs45*gdy(p)
               cs62 = (4.0_wp/9.0_wp)*cs39
               cs63 = -2.0_wp*blend_k*cs36
               cs64 = 2.0_wp*cs30 + cs41
               cs65 = cs44*cs6
               cs66 = cs65*gdx(p)
               cs67 = -2.0_wp/3.0_wp*blend_k*cs36
               cs68 = cs65*(cs13*(1.0_wp - cs62) - cs64 - cs67)
               cs69 = (4.0_wp/9.0_wp)*cs49
               cs70 = 2.0_wp*cs34 + cs51
               cs71 = cs13*(1.0_wp - cs69) - cs67 - cs70
               cs72 = cs65*gdz(p)
               cs73 = (4.0_wp/9.0_wp)*cs56
               cs74 = 2.0_wp*cs35 + cs58
               cs75 = cs13*(1.0_wp - cs73) - cs67 - cs74
               cs76 = cs65*gdy(p)
               cs77 = -3.0_wp*blend_k*cs36
               cs78 = cs11*cs41 + cs41
               cs79 = cs43*cs8
               cs80 = cs79*gdx(p)
               cs81 = cs79*(cs13*(1.0_wp - cs39) - cs37 - cs78)
               cs82 = cs11*cs51 + cs51
               cs83 = cs13*(1.0_wp - cs49) - cs37 - cs82
               cs84 = cs11*cs58 + cs58
               cs85 = cs13*(1.0_wp - cs56) - cs37 - cs84
               cs86 = cs79*gdy(p)
               cs87 = cs79*gdz(p)
               acc(p, 1) = acc(p, 1) + (gu(p))
               acc(p, 2) = acc(p, 2) + (cs0)
               acc(p, 3) = acc(p, 3) + (cs1)
               acc(p, 5) = acc(p, 5) + (-cs3*cs4)
               acc(p, 6) = acc(p, 6) + (-cs5*gdy(p))
               acc(p, 7) = acc(p, 7) + (-cs5*gdz(p))
               acc(p, 8) = acc(p, 8) + (-cs3*cs6)
               acc(p, 9) = acc(p, 9) + (-cs7*gdy(p))
               acc(p, 10) = acc(p, 10) + (-cs7*gdz(p))
               acc(p, 11) = acc(p, 11) + (-cs9*gdx(p))
               acc(p, 12) = acc(p, 12) + (-cs9*gdy(p))
               acc(p, 13) = acc(p, 13) + (-cs9*gdz(p))
               acc(p, 17) = acc(p, 17) + (cs18*(cs10*cs12 + cs15))
               acc(p, 18) = acc(p, 18) + (cs19*cs20)
               acc(p, 19) = acc(p, 19) + (cs21*gdx(p))
               acc(p, 20) = acc(p, 20) + (cs18*(cs12*cs22 + cs23))
               acc(p, 21) = acc(p, 21) + (cs21*gdy(p))
               acc(p, 22) = acc(p, 22) + (cs18*(cs12*cs24 + cs25))
               acc(p, 23) = acc(p, 23) + (cs27*(cs10*cs26 + cs15))
               acc(p, 24) = acc(p, 24) + (cs19*cs28)
               acc(p, 25) = acc(p, 25) + (cs29*gdx(p))
               acc(p, 26) = acc(p, 26) + (cs27*(cs22*cs26 + cs23))
               acc(p, 27) = acc(p, 27) + (cs29*gdy(p))
               acc(p, 28) = acc(p, 28) + (cs27*(cs24*cs26 + cs25))
               acc(p, 29) = acc(p, 29) + (cs31*(cs15 + cs30))
               acc(p, 30) = acc(p, 30) + (cs19*cs32)
               acc(p, 31) = acc(p, 31) + (cs33*gdx(p))
               acc(p, 32) = acc(p, 32) + (cs31*(cs23 + cs34))
               acc(p, 33) = acc(p, 33) + (cs33*gdy(p))
               acc(p, 34) = acc(p, 34) + (cs31*(cs25 + cs35))
               acc(p, 41) = acc(p, 41) + (cs46*(cs13*(3.0_wp - cs40) - cs37 - cs42))
               acc(p, 42) = acc(p, 42) + (cs48*gdy(p))
               acc(p, 43) = acc(p, 43) + (cs48*gdz(p))
               acc(p, 44) = acc(p, 44) + (cs46*cs53)
               acc(p, 45) = acc(p, 45) + (cs19*cs55*(-cs11 - 1.0_wp/9.0_wp*cs54 - 3.0_wp))
               acc(p, 46) = acc(p, 46) + (cs46*cs60)
               acc(p, 47) = acc(p, 47) + (cs61*(cs13*(3.0_wp - cs50) - cs37 - cs52))
               acc(p, 48) = acc(p, 48) + (cs53*cs55)
               acc(p, 49) = acc(p, 49) + (cs60*cs61)
               acc(p, 50) = acc(p, 50) + (cs55*(cs13*(3.0_wp - cs57) - cs37 - cs59))
               acc(p, 51) = acc(p, 51) + (cs66*(cs13*(3.0_wp - cs62) - cs63 - cs64))
               acc(p, 52) = acc(p, 52) + (cs68*gdy(p))
               acc(p, 53) = acc(p, 53) + (cs68*gdz(p))
               acc(p, 54) = acc(p, 54) + (cs66*cs71)
               acc(p, 55) = acc(p, 55) + (cs19*cs72*(-2.0_wp*cs11 - 4.0_wp/9.0_wp*cs54 - 3.0_wp))
               acc(p, 56) = acc(p, 56) + (cs66*cs75)
               acc(p, 57) = acc(p, 57) + (cs76*(cs13*(3.0_wp - cs69) - cs63 - cs70))
               acc(p, 58) = acc(p, 58) + (cs71*cs72)
               acc(p, 59) = acc(p, 59) + (cs75*cs76)
               acc(p, 60) = acc(p, 60) + (cs72*(cs13*(3.0_wp - cs73) - cs63 - cs74))
               acc(p, 61) = acc(p, 61) + (cs80*(cs13*(3.0_wp - cs39) - cs77 - cs78))
               acc(p, 62) = acc(p, 62) + (cs81*gdy(p))
               acc(p, 63) = acc(p, 63) + (cs81*gdz(p))
               acc(p, 64) = acc(p, 64) + (cs80*cs83)
               acc(p, 65) = acc(p, 65) + (cs80*gdy(p)*gdz(p)*(-3.0_wp*cs11 - cs54 - 3.0_wp))
               acc(p, 66) = acc(p, 66) + (cs80*cs85)
               acc(p, 67) = acc(p, 67) + (cs86*(cs13*(3.0_wp - cs49) - cs77 - cs82))
               acc(p, 68) = acc(p, 68) + (cs83*cs87)
               acc(p, 69) = acc(p, 69) + (cs85*cs86)
               acc(p, 70) = acc(p, 70) + (cs87*(cs13*(3.0_wp - cs56) - cs77 - cs84))
            end do
            if (include_q) then
               do p = 1, np
                  cs0 = (gu(p)*sqrt(gu(p)))
                  cs1 = (1.0_wp/2.0_wp)*blend_k
                  cs2 = cs0*cs1
                  cs3 = cs2*gix(p)
                  cs4 = (gdx(p)*gdx(p))
                  cs5 = (gx(p)*gx(p))
                  cs6 = -cs5
                  cs7 = cs1*gx(p)
                  cs8 = cs2*(gix(p)*gix(p)*gix(p))
                  cs9 = cs7 + 1.0_wp
                  cs10 = cs8*cs9*gdx(p)
                  cs11 = (gdy(p)*gdy(p))
                  cs12 = gdy(p)*gdz(p)
                  cs13 = (gdz(p)*gdz(p))
                  cs14 = (1.0_wp/4.0_wp)*(blend_k*blend_k)
                  cs15 = cs14*cs4
                  cs16 = (gx(p)*gx(p)*gx(p))
                  cs17 = -3.0_wp/2.0_wp*blend_k*cs16
                  cs18 = (3.0_wp/2.0_wp)*blend_k*gx(p)
                  cs19 = cs18*cs4 + 3.0_wp*cs4
                  cs20 = cs2*(gix(p)*gix(p)*gix(p)*gix(p)*gix(p))
                  cs21 = cs20*gdx(p)
                  cs22 = -1.0_wp/2.0_wp*blend_k*cs16
                  cs23 = cs20*(-cs19 - cs22 + cs5*(1.0_wp - cs15))
                  cs24 = cs11*cs14
                  cs25 = cs11*cs18 + 3.0_wp*cs11
                  cs26 = -cs22 - cs25 + cs5*(1.0_wp - cs24)
                  cs27 = cs13*cs14
                  cs28 = cs13*cs18 + 3.0_wp*cs13
                  cs29 = -cs22 - cs28 + cs5*(1.0_wp - cs27)
                  cs30 = cs20*gdy(p)
                  cs31 = cs20*gdz(p)
                  acc(p, 4) = acc(p, 4) + (cs0)
                  acc(p, 14) = acc(p, 14) + (-cs3*gdx(p))
                  acc(p, 15) = acc(p, 15) + (-cs3*gdy(p))
                  acc(p, 16) = acc(p, 16) + (-cs3*gdz(p))
                  acc(p, 35) = acc(p, 35) + (cs8*(cs4*cs7 + cs4 + cs6))
                  acc(p, 36) = acc(p, 36) + (cs10*gdy(p))
                  acc(p, 37) = acc(p, 37) + (cs10*gdz(p))
                  acc(p, 38) = acc(p, 38) + (cs8*(cs11*cs7 + cs11 + cs6))
                  acc(p, 39) = acc(p, 39) + (cs12*cs8*cs9)
                  acc(p, 40) = acc(p, 40) + (cs8*(cs13*cs7 + cs13 + cs6))
                  acc(p, 71) = acc(p, 71) + (cs21*(-cs17 - cs19 + cs5*(3.0_wp - cs15)))
                  acc(p, 72) = acc(p, 72) + (cs23*gdy(p))
                  acc(p, 73) = acc(p, 73) + (cs23*gdz(p))
                  acc(p, 74) = acc(p, 74) + (cs21*cs26)
                  acc(p, 75) = acc(p, 75) + (cs12*cs21*(-cs14*cs5 - cs18 - 3.0_wp))
                  acc(p, 76) = acc(p, 76) + (cs21*cs29)
                  acc(p, 77) = acc(p, 77) + (cs30*(-cs17 - cs25 + cs5*(3.0_wp - cs24)))
                  acc(p, 78) = acc(p, 78) + (cs26*cs31)
                  acc(p, 79) = acc(p, 79) + (cs29*cs30)
                  acc(p, 80) = acc(p, 80) + (cs31*(-cs17 - cs28 + cs5*(3.0_wp - cs27)))
               end do
            end if
         else
            ! Strip meets the band: faded atom function
            do p = 1, np
               sr = (band_end - (gx(p) - ra))*inv_delta
               fs = min(max(sr, 0.0_wp), 1.0_wp)
               ft = min(max((gx(p) - ra - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
               gfs(p) = fs
               gds(p) = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
               gfp(p, 0) = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
               gfp(p, 1) = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
               gfp(p, 2) = ft*(840.0_wp*ft + 210.0_wp) + 30.0_wp
               gfp(p, 3) = -1680.0_wp*ft - 210.0_wp
               gsp(p, 1) = fs
               gsp(p, 2) = gsp(p, 1)*fs
               gsp(p, 3) = gsp(p, 2)*fs
               gsp(p, 4) = gsp(p, 3)*fs
               gsp(p, 5) = gsp(p, 4)*fs
               gsp(p, 6) = gsp(p, 5)*fs
               gsp(p, 7) = gsp(p, 6)*fs
               gsp(p, 8) = gsp(p, 7)*fs
               gsp(p, 9) = gsp(p, 8)*fs
               gsp(p, 10) = gsp(p, 9)*fs
               gsp(p, 11) = gsp(p, 10)*fs
               gsp(p, 12) = gsp(p, 11)*fs
               gsp(p, 13) = gsp(p, 12)*fs
               gsp(p, 14) = gsp(p, 13)*fs
               gsp(p, 15) = gsp(p, 14)*fs
               fsq = sqrt(fs)
               gsh(p, 4) = gsp(p, 4)*fsq
               gsh(p, 5) = gsp(p, 5)*fsq
               gsh(p, 6) = gsp(p, 6)*fsq
               gsh(p, 7) = gsp(p, 7)*fsq
            end do
            do p = 1, np
               cs0 = gfp(p, 0)*gsp(p, 5)
               cs1 = (gu(p)*gu(p))
               cs2 = (gfp(p, 0)*gfp(p, 0))
               cs3 = cs2*gsp(p, 10)
               cs4 = (gu(p)*gu(p)*gu(p))
               cs5 = (gfp(p, 0)*gfp(p, 0)*gfp(p, 0))
               cs6 = cs5*gsp(p, 15)
               cs7 = 5.0_wp*gfp(p, 0)*gsp(p, 4) + gfp(p, 1)*gsp(p, 5)
               cs8 = gu(p)*(-1.0_wp/3.0_wp*blend_k*cs0 + cs7*gds(p))
               cs9 = cs8*gix(p)
               cs10 = (2.0_wp/3.0_wp)*blend_k
               cs11 = 10.0_wp*cs2*gsp(p, 9) + 2.0_wp*gfp(p, 0)*gfp(p, 1)*gsp(p, 10)
               cs12 = cs1*(-cs10*cs3 + cs11*gds(p))
               cs13 = cs12*gix(p)
               cs14 = 3.0_wp*gfp(p, 1)
               cs15 = cs14*cs2*gsp(p, 15) + 15.0_wp*cs5*gsp(p, 14)
               cs16 = cs4*(-blend_k*cs6 + cs15*gds(p))
               cs17 = cs16*gix(p)
               cs18 = (gdx(p)*gdx(p))
               cs19 = (gix(p)*gix(p)*gix(p))
               cs20 = cs19*cs8
               cs21 = (gix(p)*gix(p))
               cs22 = cs18*cs21
               cs23 = (blend_k*blend_k)
               cs24 = (gds(p)*gds(p))
               cs25 = 20.0_wp*gfp(p, 0)
               cs26 = gfp(p, 2)*gsp(p, 2)
               cs27 = gfp(p, 1)*gfs(p)
               cs28 = cs24*gsp(p, 3)*(cs25 + cs26 + 10.0_wp*cs27)
               cs29 = (1.0_wp/9.0_wp)*cs0*cs23 - cs10*cs7*gds(p) + cs28
               cs30 = cs29*gu(p)
               cs31 = cs20*gdy(p)
               cs32 = cs20*gdz(p)
               cs33 = (gdy(p)*gdy(p))
               cs34 = cs21*cs30
               cs35 = (gdz(p)*gdz(p))
               cs36 = cs12*cs19
               cs37 = (gfp(p, 1)*gfp(p, 1))
               cs38 = gfp(p, 0)*gfp(p, 2)
               cs39 = gsp(p, 2)*(cs37 + cs38)
               cs40 = cs24*gsp(p, 8)*(45.0_wp*cs2 + cs25*cs27 + cs39)
               cs41 = -4.0_wp/3.0_wp*blend_k*cs11*gds(p) + (4.0_wp/9.0_wp)*cs23*cs3 + 2.0_wp*cs40
               cs42 = cs1*cs41
               cs43 = cs36*gdy(p)
               cs44 = cs36*gdz(p)
               cs45 = cs21*cs42
               cs46 = cs16*cs19
               cs47 = cs27*gfp(p, 0)
               cs48 = gsp(p, 2)*(2.0_wp*cs37 + cs38)
               cs49 = cs24*gfp(p, 0)*gsp(p, 13)*(70.0_wp*cs2 + 30.0_wp*cs47 + cs48)
               cs50 = -2.0_wp*blend_k*cs15*gds(p) + cs23*cs6 + 3.0_wp*cs49
               cs51 = cs4*cs50
               cs52 = cs46*gdy(p)
               cs53 = cs46*gdz(p)
               cs54 = cs21*cs51
               cs55 = cs20*gdx(p)
               cs56 = (gdx(p)*gdx(p)*gdx(p))
               cs57 = 3.0_wp*cs56
               cs58 = (gix(p)*gix(p)*gix(p)*gix(p)*gix(p))
               cs59 = cs58*cs8
               cs60 = cs34*gdx(p)
               cs61 = (gix(p)*gix(p)*gix(p)*gix(p))
               cs62 = cs30*cs61
               cs63 = cs19*cs56
               cs64 = (blend_k*blend_k*blend_k)
               cs65 = (gds(p)*gds(p)*gds(p))
               cs66 = &
                  gu(p)*(-blend_k*cs28 - 1.0_wp/27.0_wp*cs0*cs64 + (1.0_wp/3.0_wp)*cs23*cs7*gds(p) &
                  + cs65*gsp(p, 2)*(15.0_wp*cs26 + 60.0_wp*cs27 + 60.0_wp*gfp(p, 0) + gfp(p, &
                  3)*gsp(p, 3)))
               cs67 = cs19*cs66
               cs68 = cs18*cs67
               cs69 = 3.0_wp*cs18
               cs70 = cs69*gdy(p)
               cs71 = cs34*gdy(p)
               cs72 = -cs31 + cs71
               cs73 = cs69*gdz(p)
               cs74 = cs34*gdz(p)
               cs75 = -cs32 + cs74
               cs76 = cs67*gdx(p)
               cs77 = 3.0_wp*gdx(p)
               cs78 = cs33*cs77
               cs79 = -cs55 + cs60
               cs80 = gdy(p)*gdz(p)
               cs81 = cs77*cs80
               cs82 = cs35*cs77
               cs83 = (gdy(p)*gdy(p)*gdy(p))
               cs84 = 3.0_wp*cs83
               cs85 = cs33*gdz(p)
               cs86 = 3.0_wp*cs85
               cs87 = cs35*gdy(p)
