         cs92 = &
            -cs12*cs63 - cs14*cs91 + cs60*ps2(p, 2, 4) - cs62*ps2(p, 2, 2) + cs64*ps2(p, 2, 3) + &
            cs65*ps1(p, 2, 1) + cs66*ps2(p, 2, 1) + cs90*ps1(p, 2, 4)
         cs93 = cs64*ps2(p, 4, 3)
         cs94 = cs20*ps1(p, 3, 4)
         cs95 = cs17*cs44
         cs96 = cs0*cs95
         cs97 = -cs94 + cs96
         cs98 = cs22*cs95
         cs99 = (1.0_wp/2.0_wp)*cs9*izz(p)*ps1(p, 3, 1)*s_3 - 1.0_wp/2.0_wp*cs98
         cs100 = cs10*cs16 - cs10*cs37
         cs101 = cs100 + cs13*cs95
