         cs112 = cs33*cs44
         cs113 = &
            -cs111*cs12 + cs112*ps1(p, 2, 1) + cs31*cs61 - cs35*cs67 + cs60*ps2(p, 3, 4) - &
            cs62*ps2(p, 3, 2) + cs64*ps2(p, 3, 3) + cs66*ps2(p, 3, 1)
         cs114 = cs64*ps2(p, 5, 3)
