            cs107*ps2(p, 3, 4) + cs108*ps1(p, 2, 1) + cs110*ps2(p, 3, 1) + cs113*cs14 - &
            cs18*ps3(p, 4, 4) - cs21*ps3(p, 4, 3) - cs26*ps3(p, 4, 1) + cs42*ps3(p, 4, 2)
         o3(p, 7) = &
