   pure module subroutine svdw_strip_lift_vjp(np, blend_k, s_1, s_2, s_3, ps0, ps1, ps2, w0, &
                                       w1, w2, lam0, lam1, lam2)
      !> Live points in the strip, 1..32
      integer, intent(in) :: np
      !> Blending sharpness k of u = exp(-(k/3) d)
      real(wp), intent(in) :: blend_k
      !> One-body blending weight blend_1b
      real(wp), intent(in) :: s_1
      !> Two-body blending weight blend_2b
      real(wp), intent(in) :: s_2
      !> Three-body blending weight blend_3b
      real(wp), intent(in) :: s_3
      !> Order-0 power sums of the strip, point-first; last index the kind (1 = p1, 2 =
      !> p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps0(np, nkind)
      !> Order-1 power sums of the strip, point-first; middle index the Cartesian
      !> component; last index the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps1(np, 3, nkind)
      !> Order-2 power sums of the strip, point-first; middle index the packed slot of the
      !> sorted rank-2 tuple; last index the kind (1 = p1, 2 = p2, 3 = p3, 4 = q)
      real(wp), intent(in) :: ps2(np, 6, nkind)
      !> Seed of the level-set value S
      real(wp), intent(in) :: w0(np)
      !> Seed of the spatial gradient dS/dr, point-last
      real(wp), intent(in) :: w1(3, np)
      !> Symmetric part of the (3, 3) seed of d2S/dr2, packed (xx, xy, yy, xz, yz, zz),
      !> point-last; entries not doubled
      real(wp), intent(in) :: w2(6, np)
      !> Adjoint of the order-0 power sums, layout of `ps0`
      real(wp), intent(out) :: lam0(np, nkind)
      !> Adjoint of the order-1 power sums, layout of `ps1`
      real(wp), intent(out) :: lam1(np, 3, nkind)
      !> Adjoint of the order-2 power sums, layout of `ps2`
      real(wp), intent(out) :: lam2(np, 6, nkind)

      !> Strip width of this pipeline (the order-2 width)
      integer, parameter :: nps = svdw_strip_width(2)
      !> Assembled Z per point and its reciprocal
      real(wp) :: zz(nps), izz(nps)
      !> Point-first copies of the seeds
      real(wp) :: sw0(nps), sw1(nps, 3), sw2(nps, 6)
      !> Adjoints before the store, so the point loop has no alias to test
      real(wp) :: lm0(nps, nkind), lm1(nps, 3, nkind), lm2(nps, 6, nkind)
      !> Common subexpressions of one point
      real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11, cs12, cs13
      real(wp) :: cs14, cs15, cs16, cs17, cs18, cs19, cs20, cs21, cs22, cs23, cs24, cs25
      real(wp) :: cs26, cs27, cs28, cs29, cs30, cs31, cs32, cs33, cs34, cs35, cs36, cs37
      real(wp) :: cs38, cs39, cs40, cs41, cs42, cs43, cs44, cs45, cs46, cs47, cs48, cs49
      real(wp) :: cs50, cs51, cs52, cs53, cs54, cs55, cs56, cs57, cs58, cs59, cs60, cs61
      real(wp) :: cs62, cs63, cs64, cs65, cs66, cs67, cs68, cs69, cs70, cs71, cs72, cs73
      real(wp) :: cs74, cs75, cs76, cs77, cs78, cs79, cs80, cs81, cs82, cs83, cs84, cs85
      real(wp) :: cs86, cs87, cs88, cs89, cs90, cs91
      !> Point and component indices
      integer :: p, c

      if (np < 1 .or. np > nps) error stop &
         "svdw_strip_lift_vjp: np outside 1..strip width"

      do p = 1, np
         sw0(p) = w0(p)
      end do
      do p = 1, np
         do c = 1, 3
            sw1(p, c) = w1(c, p)
         end do
         do c = 1, 6
            sw2(p, c) = w2(c, p)
         end do
      end do

      do p = 1, np
         zz(p) = &
            (1.0_wp/6.0_wp)*(ps0(p, 1)*ps0(p, 1)*ps0(p, 1))*s_3 - 1.0_wp/2.0_wp*ps0(p, &
            1)*ps0(p, 2)*s_3 + ps0(p, 3)*s_1 - 1.0_wp/2.0_wp*ps0(p, 3)*s_2 + &
            (1.0_wp/3.0_wp)*ps0(p, 3)*s_3 + (1.0_wp/2.0_wp)*(ps0(p, 4)*ps0(p, 4))*s_2
         izz(p) = 1.0_wp/zz(p)
      end do

      do p = 1, np
         cs0 = ps1(p, 1, 2)*s_3
         cs1 = (1.0_wp/2.0_wp)*cs0
         cs2 = ps0(p, 1)*s_3
         cs3 = cs2*ps1(p, 1, 1)
         cs4 = -cs1 + cs3
         cs5 = 1.0_wp/blend_k
         cs6 = cs5*izz(p)
         cs7 = cs4*cs6
         cs8 = ps1(p, 2, 2)*s_3
         cs9 = (1.0_wp/2.0_wp)*cs8
         cs10 = cs2*ps1(p, 2, 1)
         cs11 = cs10 - cs9
         cs12 = cs11*cs6
         cs13 = ps1(p, 3, 2)*s_3
         cs14 = (1.0_wp/2.0_wp)*cs13
         cs15 = cs2*ps1(p, 3, 1)
         cs16 = -cs14 + cs15
         cs17 = cs16*cs6
         cs18 = cs6*s_3
         cs19 = (1.0_wp/2.0_wp)*cs18
         cs20 = cs2*cs6
         cs21 = ps0(p, 4)*s_2
         cs22 = (1.0_wp/3.0_wp)*s_3
         cs23 = cs22 + s_1 - 1.0_wp/2.0_wp*s_2
         cs24 = ps1(p, 1, 1)*s_3
         cs25 = 3.0_wp*(ps0(p, 1)*ps0(p, 1)) - 3.0_wp*ps0(p, 2)
         cs26 = (1.0_wp/6.0_wp)*cs25
         cs27 = -cs1*ps0(p, 1) + cs21*ps1(p, 1, 4) + cs23*ps1(p, 1, 3) + cs24*cs26
         cs28 = cs5*(izz(p)*izz(p))
         cs29 = cs27*cs28
         cs30 = cs26*s_3
         cs31 = cs21*ps1(p, 2, 4) + cs23*ps1(p, 2, 3) + cs30*ps1(p, 2, 1) - cs9*ps0(p, 1)
         cs32 = cs28*cs31
         cs33 = &
            -cs14*ps0(p, 1) + cs21*ps1(p, 3, 4) + cs23*ps1(p, 3, 3) + cs30*ps1(p, 3, 1)
         cs34 = cs28*cs33
         cs35 = cs24*cs6
         cs36 = 2.0_wp*sw2(p, 2)
         cs37 = 2.0_wp*sw2(p, 4)
         cs38 = cs18*ps1(p, 2, 1)
         cs39 = 2.0_wp*sw2(p, 5)
         cs40 = cs21*cs28
         cs41 = cs28*s_2
         cs42 = (1.0_wp/2.0_wp)*cs2
         cs43 = cs28*cs42
         cs44 = cs28*ps1(p, 1, 1)
         cs45 = cs23*cs28
         cs46 = cs28*cs4
         cs47 = cs28*cs30
         cs48 = 2.0_wp*cs5*(izz(p)*izz(p)*izz(p))
         cs49 = cs28*ps1(p, 2, 1)
         cs50 = cs11*cs28
         cs51 = cs28*ps1(p, 3, 1)
         cs52 = cs41*ps1(p, 1, 4)
         cs53 = cs27*cs48
         cs54 = &
            cs29*sw1(p, 1) + cs32*sw1(p, 2) + cs34*sw1(p, 3) + cs36*(-cs31*cs53 + &
            cs40*ps2(p, 2, 4) - cs43*ps2(p, 2, 2) - cs44*cs9 + cs45*ps2(p, 2, 3) + &
            cs46*ps1(p, 2, 1) + cs47*ps2(p, 2, 1) + cs52*ps1(p, 2, 4)) + &
            cs37*(-cs14*cs44 - cs33*cs53 + cs40*ps2(p, 4, 4) - cs43*ps2(p, 4, 2) + &
            cs45*ps2(p, 4, 3) + cs46*ps1(p, 3, 1) + cs47*ps2(p, 4, 1) + cs52*ps1(p, 3, &
            4)) + cs39*(-cs14*cs49 - cs31*cs33*cs48 + cs40*ps2(p, 5, 4) + cs41*ps1(p, 2, &
            4)*ps1(p, 3, 4) - cs43*ps2(p, 5, 2) + cs45*ps2(p, 5, 3) + cs47*ps2(p, 5, 1) &
            + cs50*ps1(p, 3, 1)) - cs6*sw0(p) + sw2(p, 1)*(-cs1*cs44 - (cs27*cs27)*cs48 &
            + cs40*ps2(p, 1, 4) + cs41*(ps1(p, 1, 4)*ps1(p, 1, 4)) - cs43*ps2(p, 1, 2) + &
            cs45*ps2(p, 1, 3) + cs46*ps1(p, 1, 1) + cs47*ps2(p, 1, 1)) + sw2(p, &
            3)*(-(cs31*cs31)*cs48 + cs40*ps2(p, 3, 4) + cs41*(ps1(p, 2, 4)*ps1(p, 2, 4)) &
            - cs43*ps2(p, 3, 2) + cs45*ps2(p, 3, 3) + cs47*ps2(p, 3, 1) - cs49*cs9 + &
            cs50*ps1(p, 2, 1)) + sw2(p, 6)*(-cs14*cs51 + cs16*cs51 - (cs33*cs33)*cs48 + &
            cs40*ps2(p, 6, 4) + cs41*(ps1(p, 3, 4)*ps1(p, 3, 4)) - cs43*ps2(p, 6, 2) + &
            cs45*ps2(p, 6, 3) + cs47*ps2(p, 6, 1))
         cs55 = cs18*cs26
         cs56 = cs30*cs32
         cs57 = -cs10*cs6 + cs6*cs9
         cs58 = cs14*cs6 - cs15*cs6
         cs59 = cs30*cs34 + cs58
         cs60 = -cs7
         cs61 = cs22*cs25
         cs62 = cs29*cs30 + cs60
         cs63 = -cs12
         cs64 = cs6*cs61
         cs65 = ps1(p, 2, 1)*s_3
         cs66 = ps1(p, 3, 1)*s_3
         cs67 = (1.0_wp/2.0_wp)*cs24
         cs68 = (1.0_wp/2.0_wp)*cs29
         cs69 = cs42*cs6
         cs70 = -cs32*cs42 + (1.0_wp/2.0_wp)*cs5*izz(p)*ps1(p, 2, 1)*s_3
         cs71 = -cs34*cs42 + (1.0_wp/2.0_wp)*cs5*izz(p)*ps1(p, 3, 1)*s_3
         cs72 = -cs29*cs42 + (1.0_wp/2.0_wp)*cs5*izz(p)*ps1(p, 1, 1)*s_3
         cs73 = cs23*cs6
         cs74 = cs23*cs36
         cs75 = cs23*cs34
         cs76 = 2.0_wp*s_1 - s_2 + (2.0_wp/3.0_wp)*s_3
         cs77 = cs6*s_2
         cs78 = cs77*ps1(p, 1, 4)
         cs79 = cs77*ps1(p, 2, 4)
         cs80 = cs77*ps1(p, 3, 4)
         cs81 = ps1(p, 1, 4)*s_2
         cs82 = ps1(p, 2, 4)*s_2
         cs83 = ps1(p, 3, 4)*s_2
         cs84 = cs29*s_2
         cs85 = cs21*cs6
         cs86 = cs21*cs29
         cs87 = cs21*cs32
         cs88 = -cs79 + cs87
         cs89 = cs21*cs34
         cs90 = -cs80 + cs89
         cs91 = -cs78 + cs86
         lm0(p, 1) = &
            -cs12*sw1(p, 2) - cs17*sw1(p, 3) + cs30*cs54 + cs36*(cs11*cs29 + cs19*ps2(p, &
            2, 2) - cs20*ps2(p, 2, 1) + cs32*cs4 - cs35*ps1(p, 2, 1)) + cs37*(cs16*cs29 &
            + cs19*ps2(p, 4, 2) - cs20*ps2(p, 4, 1) + cs34*cs4 - cs35*ps1(p, 3, 1)) + &
            cs39*(cs11*cs34 + cs16*cs32 + cs19*ps2(p, 5, 2) - cs20*ps2(p, 5, 1) - &
            cs38*ps1(p, 3, 1)) - cs7*sw1(p, 1) + sw2(p, 1)*(-cs18*(ps1(p, 1, 1)*ps1(p, &
            1, 1)) + cs19*ps2(p, 1, 2) - cs20*ps2(p, 1, 1) + cs29*(-cs0 + 2.0_wp*cs3)) + &
            sw2(p, 3)*(-cs18*(ps1(p, 2, 1)*ps1(p, 2, 1)) + cs19*ps2(p, 3, 2) - &
            cs20*ps2(p, 3, 1) + cs32*(2.0_wp*cs10 - cs8)) + sw2(p, 6)*(-cs18*(ps1(p, 3, &
            1)*ps1(p, 3, 1)) + cs19*ps2(p, 6, 2) - cs20*ps2(p, 6, 1) + cs34*(-cs13 + &
            2.0_wp*cs15))
         lm1(p, 1, 1) = &
            cs36*(cs56 + cs57) + cs37*cs59 - cs55*sw1(p, 1) + sw2(p, 1)*(cs1*cs6 + &
            cs29*cs61 - cs3*cs6 + cs60)
         lm1(p, 2, 1) = &
            cs36*cs62 + cs39*cs59 - cs55*sw1(p, 2) + sw2(p, 3)*(cs32*cs61 + cs57 + cs63)
         lm1(p, 3, 1) = &
            cs37*cs62 + cs39*(cs56 + cs63) - cs55*sw1(p, 3) + sw2(p, 6)*(-cs17 + &
            cs34*cs61 + cs58)
         lm2(p, 1, 1) = -cs55*sw2(p, 1)
         lm2(p, 2, 1) = -cs64*sw2(p, 2)
         lm2(p, 4, 1) = -cs64*sw2(p, 4)
         lm2(p, 3, 1) = -cs55*sw2(p, 3)
         lm2(p, 5, 1) = -cs64*sw2(p, 5)
         lm2(p, 6, 1) = -cs55*sw2(p, 6)
         lm0(p, 2) = &
            (1.0_wp/2.0_wp)*cs18*ps1(p, 3, 1)*sw1(p, 3) + (1.0_wp/2.0_wp)*cs35*sw1(p, 1) &
            + cs36*(-cs32*cs67 + (1.0_wp/2.0_wp)*cs5*izz(p)*ps2(p, 2, 1)*s_3 - &
            cs65*cs68) + cs37*(-cs34*cs67 + (1.0_wp/2.0_wp)*cs5*izz(p)*ps2(p, 4, 1)*s_3 &
            - cs66*cs68) + (1.0_wp/2.0_wp)*cs38*sw1(p, 2) + &
            cs39*(-1.0_wp/2.0_wp*cs32*cs66 - 1.0_wp/2.0_wp*cs34*cs65 + &
            (1.0_wp/2.0_wp)*cs5*izz(p)*ps2(p, 5, 1)*s_3) - cs42*cs54 + sw2(p, &
            1)*(-cs24*cs29 + (1.0_wp/2.0_wp)*cs5*izz(p)*ps2(p, 1, 1)*s_3) + sw2(p, &
            3)*(-cs32*cs65 + (1.0_wp/2.0_wp)*cs5*izz(p)*ps2(p, 3, 1)*s_3) + sw2(p, &
            6)*(-cs34*cs66 + (1.0_wp/2.0_wp)*cs5*izz(p)*ps2(p, 6, 1)*s_3)
         lm1(p, 1, 2) = &
            cs36*cs70 + cs37*cs71 + cs69*sw1(p, 1) + sw2(p, 1)*(-cs2*cs29 + &
            cs5*izz(p)*ps1(p, 1, 1)*s_3)
         lm1(p, 2, 2) = &
            cs36*cs72 + cs39*cs71 + cs69*sw1(p, 2) + sw2(p, 3)*(-cs2*cs32 + &
            cs5*izz(p)*ps1(p, 2, 1)*s_3)
         lm1(p, 3, 2) = &
            cs37*cs72 + cs39*cs70 + cs69*sw1(p, 3) + sw2(p, 6)*(-cs2*cs34 + &
            cs5*izz(p)*ps1(p, 3, 1)*s_3)
         lm2(p, 1, 2) = cs69*sw2(p, 1)
         lm2(p, 2, 2) = cs20*sw2(p, 2)
         lm2(p, 4, 2) = cs20*sw2(p, 4)
         lm2(p, 3, 2) = cs69*sw2(p, 3)
         lm2(p, 5, 2) = cs20*sw2(p, 5)
         lm2(p, 6, 2) = cs69*sw2(p, 6)
         lm0(p, 3) = cs23*cs54
         lm1(p, 1, 3) = cs29*cs76*sw2(p, 1) + cs32*cs74 + cs37*cs75 - cs73*sw1(p, 1)
         lm1(p, 2, 3) = cs29*cs74 + cs32*cs76*sw2(p, 3) + cs39*cs75 - cs73*sw1(p, 2)
         lm1(p, 3, 3) = &
            cs23*cs29*cs37 + cs23*cs32*cs39 + cs34*cs76*sw2(p, 6) - cs73*sw1(p, 3)
         lm2(p, 1, 3) = -cs73*sw2(p, 1)
         lm2(p, 2, 3) = -cs36*cs73
         lm2(p, 4, 3) = -cs37*cs73
         lm2(p, 3, 3) = -cs73*sw2(p, 3)
         lm2(p, 5, 3) = -cs39*cs73
         lm2(p, 6, 3) = -cs73*sw2(p, 6)
         lm0(p, 4) = &
            cs21*cs54 + cs36*(cs32*cs81 - cs77*ps2(p, 2, 4) + cs84*ps1(p, 2, 4)) + &
            cs37*(cs34*cs81 - cs77*ps2(p, 4, 4) + cs84*ps1(p, 3, 4)) + cs39*(cs32*cs83 + &
            cs34*cs82 - cs77*ps2(p, 5, 4)) - cs78*sw1(p, 1) - cs79*sw1(p, 2) - &
            cs80*sw1(p, 3) + sw2(p, 1)*(2.0_wp*cs29*cs81 - cs77*ps2(p, 1, 4)) + sw2(p, &
            3)*(2.0_wp*cs32*cs82 - cs77*ps2(p, 3, 4)) + sw2(p, 6)*(2.0_wp*cs34*cs83 - &
            cs77*ps2(p, 6, 4))
         lm1(p, 1, 4) = &
            cs36*cs88 + cs37*cs90 - cs85*sw1(p, 1) + sw2(p, 1)*(-2.0_wp*cs78 + &
            2.0_wp*cs86)
         lm1(p, 2, 4) = &
            cs36*cs91 + cs39*cs90 - cs85*sw1(p, 2) + sw2(p, 3)*(-2.0_wp*cs79 + &
            2.0_wp*cs87)
         lm1(p, 3, 4) = &
            cs37*cs91 + cs39*cs88 - cs85*sw1(p, 3) + sw2(p, 6)*(-2.0_wp*cs80 + &
            2.0_wp*cs89)
         lm2(p, 1, 4) = -cs85*sw2(p, 1)
         lm2(p, 2, 4) = -cs36*cs85
         lm2(p, 4, 4) = -cs37*cs85
         lm2(p, 3, 4) = -cs85*sw2(p, 3)
         lm2(p, 5, 4) = -cs39*cs85
         lm2(p, 6, 4) = -cs85*sw2(p, 6)
      end do

      lam0 = lm0(1:np, :)
      lam1 = lm1(1:np, :, :)
      lam2 = lm2(1:np, :, :)

   end subroutine svdw_strip_lift_vjp

   pure module subroutine svdw_strip_vjp(np, points, nat, centers, radii, blend_k, include_q, &
                                  fade_start, fade_width, lam0, lam1, lam2, cache_x, &
                                  cache_inv_x, cache_u, res, n_zero)
      !> Live points in the strip, 1..32
      integer, intent(in) :: np
      !> Strip points, point-last; those of stage 1
      real(wp), intent(in) :: points(3, np)
      !> Atoms in the shared list
      integer, intent(in) :: nat
      !> Atom centers of the shared list
      real(wp), intent(in) :: centers(3, nat)
      !> Atom radii R_a
      real(wp), intent(in) :: radii(nat)
      !> Blending sharpness k of u = exp(-(k/3) d)
      real(wp), intent(in) :: blend_k
      !> Contract the kind-4 (`q`) adjoints; pass `blend_2b /= 0`
      logical, intent(in) :: include_q
      !> Fade onset X_on in d_A, as in stage 1; huge(0.0_wp) for no fade
      real(wp), intent(in) :: fade_start
      !> Fade band width Delta in d_A, as in stage 1; > 0
      real(wp), intent(in) :: fade_width
      !> Adjoint of the order-0 power sums from `svdw_strip_lift_vjp`
      real(wp), intent(in) :: lam0(np, nkind)
      !> Adjoint of the order-1 power sums from `svdw_strip_lift_vjp`
      real(wp), intent(in) :: lam1(np, 3, nkind)
      !> Adjoint of the order-2 power sums from `svdw_strip_lift_vjp`
      real(wp), intent(in) :: lam2(np, 6, nkind)
      !> Distance ||r_p - R_A|| per point and atom, stage-1 cache
      real(wp), intent(in) :: cache_x(np, nat)
      !> Reciprocal distance per point and atom, stage-1 cache
      real(wp), intent(in) :: cache_inv_x(np, nat)
      !> Gate-masked unfaded screening factor u_A per point and atom, stage-1 cache
      real(wp), intent(in) :: cache_u(np, nat)
      !> Nuclear gradient of the weighted jet per atom and point; exact zeros out of reach
      real(wp), intent(out) :: res(3, nat, np)
      !> Point-atom pairs at zero distance; nonzero means `res` is not finite there
      integer, intent(out) :: n_zero

      !> Strip width of this pipeline (the order-2 width)
      integer, parameter :: nps = svdw_strip_width(2)
      !> Point-first copy of the strip
      real(wp) :: px(nps), py(nps), pz(nps)
      !> Kind-summed adjoint times radial derivative, one column per (rank, j)
      real(wp) :: ml(nps, 25)
      !> Result components of one atom, point-first
      real(wp) :: r1(nps), r2(nps), r3(nps)
      !> Strip bounding box
      real(wp) :: lo(3), hi(3)
      !> Atom data, box distances and hoisted constants
      real(wp) :: cx, cy, cz, ra, ex, ey, ez, dnear, dfar, band_end, inv_delta
      !> Displacement and reciprocal distance of one point-atom pair
      real(wp) :: dx, dy, dz, ix
      !> Fade of one atom against the strip, point-first
      real(wp) :: gfs(nps), gds(nps), gfp(nps, 0:3)
      !> Integer and half-integer powers of the fade variable, point-first
      real(wp) :: gsp(nps, 15), gsh(nps, 0:15)
      !> Fade scalars
      real(wp) :: sr, fs, ft, fsq
      !> Common subexpressions of one point-atom pair
      real(wp) :: cs0, cs1, cs2, cs3, cs4, cs5, cs6, cs7, cs8, cs9, cs10, cs11, cs12, cs13
      real(wp) :: cs14, cs15, cs16, cs17, cs18, cs19, cs20, cs21, cs22, cs23, cs24, cs25
      real(wp) :: cs26, cs27, cs28, cs29, cs30, cs31, cs32, cs33, cs34, cs35, cs36, cs37
      real(wp) :: cs38, cs39, cs40, cs41, cs42, cs43, cs44, cs45, cs46, cs47, cs48, cs49
      real(wp) :: cs50, cs51, cs52, cs53, cs54, cs55, cs56, cs57
      !> Point and atom indices
      integer :: p, a
      !> Atom beyond the band for the whole strip
      logical :: skip

      if (np < 1 .or. np > nps) error stop &
         "svdw_strip_vjp: np outside 1..strip width"
      if (.not. fade_width > 0.0_wp) error stop &
         "svdw_strip_vjp: fade_width must be positive"

      do p = 1, np
         px(p) = points(1, p)
         py(p) = points(2, p)
         pz(p) = points(3, p)
      end do
      lo(1) = minval(px(1:np))
      lo(2) = minval(py(1:np))
      lo(3) = minval(pz(1:np))
      hi(1) = maxval(px(1:np))
      hi(2) = maxval(py(1:np))
      hi(3) = maxval(pz(1:np))
      band_end = fade_start + fade_width
      inv_delta = 1.0_wp/fade_width
      n_zero = 0

      do a = 1, nat
         cx = centers(1, a)
         cy = centers(2, a)
         cz = centers(3, a)
         ra = radii(a)
         n_zero = n_zero + count(cache_x(1:np, a) == 0.0_wp)

         ! Nearest and farthest box point, as signed sphere distances
         ex = max(lo(1) - cx, 0.0_wp, cx - hi(1))
         ey = max(lo(2) - cy, 0.0_wp, cy - hi(2))
         ez = max(lo(3) - cz, 0.0_wp, cz - hi(3))
         dnear = sqrt(ex*ex + ey*ey + ez*ez) - ra
         ex = max(abs(cx - lo(1)), abs(cx - hi(1)))
         ey = max(abs(cy - lo(2)), abs(cy - hi(2)))
         ez = max(abs(cz - lo(3)), abs(cz - hi(3)))
         dfar = sqrt(ex*ex + ey*ey + ez*ez) - ra
         skip = dnear >= band_end
         if (skip) then
            ! Beyond the band for every point: exact zeros
            do p = 1, np
               res(1, a, p) = 0.0_wp
               res(2, a, p) = 0.0_wp
               res(3, a, p) = 0.0_wp
            end do
            cycle
         end if

         if (dfar <= fade_start) then
            ! Plateau for the whole strip: plain atom function
            do p = 1, np
               cs0 = (1.0_wp/3.0_wp)*blend_k*cache_u(p, a)
               cs1 = (cache_u(p, a)*cache_u(p, a)*cache_u(p, a))
               cs2 = blend_k*cs1
               cs3 = (cache_u(p, a)*cache_u(p, a))
               cs4 = (2.0_wp/3.0_wp)*blend_k*cs3
               cs5 = (blend_k*blend_k)
               cs6 = (1.0_wp/9.0_wp)*cs5*cache_u(p, a)
               cs7 = cs1*cs5
               cs8 = (4.0_wp/9.0_wp)*cs3*cs5
               cs9 = (blend_k*blend_k*blend_k)
               cs10 = (1.0_wp/27.0_wp)*cs9*cache_u(p, a)
               cs11 = cs1*cs9
               cs12 = (8.0_wp/27.0_wp)*cs3*cs9
               ml(p, 1) = -cs0*lam0(p, 1) - cs2*lam0(p, 3) - cs4*lam0(p, 2)
               ml(p, 2) = -cs0*lam1(p, 1, 1) - cs2*lam1(p, 1, 3) - cs4*lam1(p, 1, 2)
               ml(p, 3) = cs6*lam1(p, 1, 1) + cs7*lam1(p, 1, 3) + cs8*lam1(p, 1, 2)
               ml(p, 4) = -cs0*lam1(p, 2, 1) - cs2*lam1(p, 2, 3) - cs4*lam1(p, 2, 2)
               ml(p, 5) = cs6*lam1(p, 2, 1) + cs7*lam1(p, 2, 3) + cs8*lam1(p, 2, 2)
               ml(p, 6) = -cs0*lam1(p, 3, 1) - cs2*lam1(p, 3, 3) - cs4*lam1(p, 3, 2)
               ml(p, 7) = cs6*lam1(p, 3, 1) + cs7*lam1(p, 3, 3) + cs8*lam1(p, 3, 2)
               ml(p, 8) = -cs0*lam2(p, 1, 1) - cs2*lam2(p, 1, 3) - cs4*lam2(p, 1, 2)
               ml(p, 9) = cs6*lam2(p, 1, 1) + cs7*lam2(p, 1, 3) + cs8*lam2(p, 1, 2)
               ml(p, 10) = -cs10*lam2(p, 1, 1) - cs11*lam2(p, 1, 3) - cs12*lam2(p, 1, 2)
               ml(p, 11) = -cs0*lam2(p, 2, 1) - cs2*lam2(p, 2, 3) - cs4*lam2(p, 2, 2)
               ml(p, 12) = cs6*lam2(p, 2, 1) + cs7*lam2(p, 2, 3) + cs8*lam2(p, 2, 2)
               ml(p, 13) = -cs10*lam2(p, 2, 1) - cs11*lam2(p, 2, 3) - cs12*lam2(p, 2, 2)
               ml(p, 14) = -cs0*lam2(p, 4, 1) - cs2*lam2(p, 4, 3) - cs4*lam2(p, 4, 2)
               ml(p, 15) = cs6*lam2(p, 4, 1) + cs7*lam2(p, 4, 3) + cs8*lam2(p, 4, 2)
               ml(p, 16) = -cs10*lam2(p, 4, 1) - cs11*lam2(p, 4, 3) - cs12*lam2(p, 4, 2)
               ml(p, 17) = -cs0*lam2(p, 3, 1) - cs2*lam2(p, 3, 3) - cs4*lam2(p, 3, 2)
               ml(p, 18) = cs6*lam2(p, 3, 1) + cs7*lam2(p, 3, 3) + cs8*lam2(p, 3, 2)
               ml(p, 19) = -cs10*lam2(p, 3, 1) - cs11*lam2(p, 3, 3) - cs12*lam2(p, 3, 2)
               ml(p, 20) = -cs0*lam2(p, 5, 1) - cs2*lam2(p, 5, 3) - cs4*lam2(p, 5, 2)
               ml(p, 21) = cs6*lam2(p, 5, 1) + cs7*lam2(p, 5, 3) + cs8*lam2(p, 5, 2)
               ml(p, 22) = -cs10*lam2(p, 5, 1) - cs11*lam2(p, 5, 3) - cs12*lam2(p, 5, 2)
               ml(p, 23) = -cs0*lam2(p, 6, 1) - cs2*lam2(p, 6, 3) - cs4*lam2(p, 6, 2)
               ml(p, 24) = cs6*lam2(p, 6, 1) + cs7*lam2(p, 6, 3) + cs8*lam2(p, 6, 2)
               ml(p, 25) = -cs10*lam2(p, 6, 1) - cs11*lam2(p, 6, 3) - cs12*lam2(p, 6, 2)
            end do
            if (include_q) then
               do p = 1, np
                  cs0 = (cache_u(p, a)*sqrt(cache_u(p, a)))
                  cs1 = (1.0_wp/2.0_wp)*blend_k*cs0
                  cs2 = (1.0_wp/4.0_wp)*(blend_k*blend_k)*cs0
                  cs3 = (1.0_wp/8.0_wp)*(blend_k*blend_k*blend_k)*cs0
                  ml(p, 1) = ml(p, 1) + (-cs1*lam0(p, 4))
                  ml(p, 2) = ml(p, 2) + (-cs1*lam1(p, 1, 4))
                  ml(p, 3) = ml(p, 3) + (cs2*lam1(p, 1, 4))
                  ml(p, 4) = ml(p, 4) + (-cs1*lam1(p, 2, 4))
                  ml(p, 5) = ml(p, 5) + (cs2*lam1(p, 2, 4))
                  ml(p, 6) = ml(p, 6) + (-cs1*lam1(p, 3, 4))
                  ml(p, 7) = ml(p, 7) + (cs2*lam1(p, 3, 4))
                  ml(p, 8) = ml(p, 8) + (-cs1*lam2(p, 1, 4))
                  ml(p, 9) = ml(p, 9) + (cs2*lam2(p, 1, 4))
                  ml(p, 10) = ml(p, 10) + (-cs3*lam2(p, 1, 4))
                  ml(p, 11) = ml(p, 11) + (-cs1*lam2(p, 2, 4))
                  ml(p, 12) = ml(p, 12) + (cs2*lam2(p, 2, 4))
                  ml(p, 13) = ml(p, 13) + (-cs3*lam2(p, 2, 4))
                  ml(p, 14) = ml(p, 14) + (-cs1*lam2(p, 4, 4))
                  ml(p, 15) = ml(p, 15) + (cs2*lam2(p, 4, 4))
                  ml(p, 16) = ml(p, 16) + (-cs3*lam2(p, 4, 4))
                  ml(p, 17) = ml(p, 17) + (-cs1*lam2(p, 3, 4))
                  ml(p, 18) = ml(p, 18) + (cs2*lam2(p, 3, 4))
                  ml(p, 19) = ml(p, 19) + (-cs3*lam2(p, 3, 4))
                  ml(p, 20) = ml(p, 20) + (-cs1*lam2(p, 5, 4))
                  ml(p, 21) = ml(p, 21) + (cs2*lam2(p, 5, 4))
                  ml(p, 22) = ml(p, 22) + (-cs3*lam2(p, 5, 4))
                  ml(p, 23) = ml(p, 23) + (-cs1*lam2(p, 6, 4))
                  ml(p, 24) = ml(p, 24) + (cs2*lam2(p, 6, 4))
                  ml(p, 25) = ml(p, 25) + (-cs3*lam2(p, 6, 4))
               end do
            end if
         else
            ! Strip meets the band: faded atom function
            do p = 1, np
               sr = (band_end - (cache_x(p, a) - ra))*inv_delta
               fs = min(max(sr, 0.0_wp), 1.0_wp)
               ft = min(max((cache_x(p, a) - ra - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
               gfs(p) = fs
               gds(p) = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
               gfp(p, 0) = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
               gfp(p, 1) = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
               gfp(p, 2) = ft*(840.0_wp*ft + 210.0_wp) + 30.0_wp
               gfp(p, 3) = -1680.0_wp*ft - 210.0_wp
               gsp(p, 1) = fs
               gsp(p, 2) = gsp(p, 1)*fs
               gsp(p, 3) = gsp(p, 2)*fs
               gsp(p, 4) = gsp(p, 3)*fs
               gsp(p, 5) = gsp(p, 4)*fs
               gsp(p, 6) = gsp(p, 5)*fs
               gsp(p, 7) = gsp(p, 6)*fs
               gsp(p, 8) = gsp(p, 7)*fs
               gsp(p, 9) = gsp(p, 8)*fs
               gsp(p, 10) = gsp(p, 9)*fs
               gsp(p, 11) = gsp(p, 10)*fs
               gsp(p, 12) = gsp(p, 11)*fs
               gsp(p, 13) = gsp(p, 12)*fs
               gsp(p, 14) = gsp(p, 13)*fs
               gsp(p, 15) = gsp(p, 14)*fs
               fsq = sqrt(fs)
               gsh(p, 4) = gsp(p, 4)*fsq
               gsh(p, 5) = gsp(p, 5)*fsq
               gsh(p, 6) = gsp(p, 6)*fsq
               gsh(p, 7) = gsp(p, 7)*fsq
            end do
            do p = 1, np
               cs0 = gfp(p, 0)*gsp(p, 5)
               cs1 = 5.0_wp*gfp(p, 0)*gsp(p, 4) + gfp(p, 1)*gsp(p, 5)
               cs2 = cache_u(p, a)*(-1.0_wp/3.0_wp*blend_k*cs0 + cs1*gds(p))
               cs3 = (cache_u(p, a)*cache_u(p, a))
               cs4 = (2.0_wp/3.0_wp)*blend_k
               cs5 = (gfp(p, 0)*gfp(p, 0))
               cs6 = cs5*gsp(p, 10)
               cs7 = 10.0_wp*cs5*gsp(p, 9) + 2.0_wp*gfp(p, 0)*gfp(p, 1)*gsp(p, 10)
               cs8 = cs3*(-cs4*cs6 + cs7*gds(p))
               cs9 = (cache_u(p, a)*cache_u(p, a)*cache_u(p, a))
               cs10 = (gfp(p, 0)*gfp(p, 0)*gfp(p, 0))
               cs11 = cs10*gsp(p, 15)
               cs12 = 3.0_wp*gfp(p, 1)
               cs13 = 15.0_wp*cs10*gsp(p, 14) + cs12*cs5*gsp(p, 15)
               cs14 = cs9*(-blend_k*cs11 + cs13*gds(p))
               cs15 = (blend_k*blend_k)
               cs16 = (gds(p)*gds(p))
               cs17 = 20.0_wp*gfp(p, 0)
               cs18 = gfp(p, 2)*gsp(p, 2)
               cs19 = gfp(p, 1)*gfs(p)
               cs20 = cs16*gsp(p, 3)*(cs17 + cs18 + 10.0_wp*cs19)
               cs21 = cache_u(p, a)*((1.0_wp/9.0_wp)*cs0*cs15 - cs1*cs4*gds(p) + cs20)
               cs22 = (gfp(p, 1)*gfp(p, 1))
               cs23 = gfp(p, 0)*gfp(p, 2)
               cs24 = gsp(p, 2)*(cs22 + cs23)
               cs25 = cs16*gsp(p, 8)*(cs17*cs19 + cs24 + 45.0_wp*cs5)
               cs26 = &
                  cs3*(-4.0_wp/3.0_wp*blend_k*cs7*gds(p) + (4.0_wp/9.0_wp)*cs15*cs6 + &
                  2.0_wp*cs25)
               cs27 = cs19*gfp(p, 0)
               cs28 = gsp(p, 2)*(2.0_wp*cs22 + cs23)
               cs29 = cs16*gfp(p, 0)*gsp(p, 13)*(30.0_wp*cs27 + cs28 + 70.0_wp*cs5)
               cs30 = cs9*(-2.0_wp*blend_k*cs13*gds(p) + cs11*cs15 + 3.0_wp*cs29)
               cs31 = (blend_k*blend_k*blend_k)
               cs32 = (gds(p)*gds(p)*gds(p))
               cs33 = &
                  cache_u(p, a)*(-blend_k*cs20 - 1.0_wp/27.0_wp*cs0*cs31 + &
                  (1.0_wp/3.0_wp)*cs1*cs15*gds(p) + cs32*gsp(p, 2)*(15.0_wp*cs18 + &
                  60.0_wp*cs19 + 60.0_wp*gfp(p, 0) + gfp(p, 3)*gsp(p, 3)))
               cs34 = &
                  cs3*(-4.0_wp*blend_k*cs25 + (4.0_wp/3.0_wp)*cs15*cs7*gds(p) - &
                  8.0_wp/27.0_wp*cs31*cs6 + 2.0_wp*cs32*gsp(p, 7)*(30.0_wp*cs24 + &
                  270.0_wp*cs27 + 360.0_wp*cs5 + gsp(p, 3)*(cs12*gfp(p, 2) + gfp(p, &
                  0)*gfp(p, 3))))
               cs35 = &
                  cs9*(-9.0_wp*blend_k*cs29 - cs11*cs31 + 3.0_wp*cs13*cs15*gds(p) + &
                  3.0_wp*cs32*gsp(p, 12)*(910.0_wp*cs10 + 630.0_wp*cs19*cs5 + &
                  45.0_wp*cs28*gfp(p, 0) + gsp(p, 3)*(6.0_wp*cs23*gfp(p, 1) + cs5*gfp(p, &
                  3) + 2.0_wp*(gfp(p, 1)*gfp(p, 1)*gfp(p, 1)))))
               ml(p, 1) = cs14*lam0(p, 3) + cs2*lam0(p, 1) + cs8*lam0(p, 2)
               ml(p, 2) = cs14*lam1(p, 1, 3) + cs2*lam1(p, 1, 1) + cs8*lam1(p, 1, 2)
               ml(p, 3) = cs21*lam1(p, 1, 1) + cs26*lam1(p, 1, 2) + cs30*lam1(p, 1, 3)
               ml(p, 4) = cs14*lam1(p, 2, 3) + cs2*lam1(p, 2, 1) + cs8*lam1(p, 2, 2)
               ml(p, 5) = cs21*lam1(p, 2, 1) + cs26*lam1(p, 2, 2) + cs30*lam1(p, 2, 3)
               ml(p, 6) = cs14*lam1(p, 3, 3) + cs2*lam1(p, 3, 1) + cs8*lam1(p, 3, 2)
               ml(p, 7) = cs21*lam1(p, 3, 1) + cs26*lam1(p, 3, 2) + cs30*lam1(p, 3, 3)
               ml(p, 8) = cs14*lam2(p, 1, 3) + cs2*lam2(p, 1, 1) + cs8*lam2(p, 1, 2)
               ml(p, 9) = cs21*lam2(p, 1, 1) + cs26*lam2(p, 1, 2) + cs30*lam2(p, 1, 3)
               ml(p, 10) = cs33*lam2(p, 1, 1) + cs34*lam2(p, 1, 2) + cs35*lam2(p, 1, 3)
               ml(p, 11) = cs14*lam2(p, 2, 3) + cs2*lam2(p, 2, 1) + cs8*lam2(p, 2, 2)
               ml(p, 12) = cs21*lam2(p, 2, 1) + cs26*lam2(p, 2, 2) + cs30*lam2(p, 2, 3)
               ml(p, 13) = cs33*lam2(p, 2, 1) + cs34*lam2(p, 2, 2) + cs35*lam2(p, 2, 3)
               ml(p, 14) = cs14*lam2(p, 4, 3) + cs2*lam2(p, 4, 1) + cs8*lam2(p, 4, 2)
               ml(p, 15) = cs21*lam2(p, 4, 1) + cs26*lam2(p, 4, 2) + cs30*lam2(p, 4, 3)
               ml(p, 16) = cs33*lam2(p, 4, 1) + cs34*lam2(p, 4, 2) + cs35*lam2(p, 4, 3)
               ml(p, 17) = cs14*lam2(p, 3, 3) + cs2*lam2(p, 3, 1) + cs8*lam2(p, 3, 2)
               ml(p, 18) = cs21*lam2(p, 3, 1) + cs26*lam2(p, 3, 2) + cs30*lam2(p, 3, 3)
               ml(p, 19) = cs33*lam2(p, 3, 1) + cs34*lam2(p, 3, 2) + cs35*lam2(p, 3, 3)
               ml(p, 20) = cs14*lam2(p, 5, 3) + cs2*lam2(p, 5, 1) + cs8*lam2(p, 5, 2)
               ml(p, 21) = cs21*lam2(p, 5, 1) + cs26*lam2(p, 5, 2) + cs30*lam2(p, 5, 3)
               ml(p, 22) = cs33*lam2(p, 5, 1) + cs34*lam2(p, 5, 2) + cs35*lam2(p, 5, 3)
               ml(p, 23) = cs14*lam2(p, 6, 3) + cs2*lam2(p, 6, 1) + cs8*lam2(p, 6, 2)
               ml(p, 24) = cs21*lam2(p, 6, 1) + cs26*lam2(p, 6, 2) + cs30*lam2(p, 6, 3)
               ml(p, 25) = cs33*lam2(p, 6, 1) + cs34*lam2(p, 6, 2) + cs35*lam2(p, 6, 3)
            end do
            if (include_q) then
               do p = 1, np
                  cs0 = (cache_u(p, a)*sqrt(cache_u(p, a)))
                  cs1 = (gfp(p, 0)*sqrt(gfp(p, 0)))
                  cs2 = cs1*gsh(p, 7)
                  cs3 = sqrt(gfp(p, 0))
                  cs4 = cs3*gfp(p, 1)
                  cs5 = (15.0_wp/2.0_wp)*cs1*gsh(p, 6) + (3.0_wp/2.0_wp)*cs4*gsh(p, 7)
                  cs6 = cs0*(-1.0_wp/2.0_wp*blend_k*cs2 + cs5*gds(p))
                  cs7 = (blend_k*blend_k)
                  cs8 = cs4*gfs(p)
                  cs9 = 1.0_wp/cs3
                  cs10 = gsp(p, 2)*(2.0_wp*cs3*gfp(p, 2) + cs9*(gfp(p, 1)*gfp(p, 1)))
                  cs11 = (gds(p)*gds(p))*gsh(p, 5)*(65.0_wp*cs1 + cs10 + 30.0_wp*cs8)
                  cs12 = &
                     cs0*(-blend_k*cs5*gds(p) + (3.0_wp/4.0_wp)*cs11 + &
                     (1.0_wp/4.0_wp)*cs2*cs7)
                  cs13 = &
                     cs0*(-1.0_wp/8.0_wp*(blend_k*blend_k*blend_k)*cs2 - &
                     9.0_wp/8.0_wp*blend_k*cs11 + (3.0_wp/4.0_wp)*cs5*cs7*gds(p) + &
                     (3.0_wp/8.0_wp)*(gds(p)*gds(p)*gds(p))*gsh(p, 4)*(715.0_wp*cs1 + &
                     45.0_wp*cs10 + 585.0_wp*cs8 + gsp(p, 3)*(4.0_wp*cs3*gfp(p, 3) + &
                     6.0_wp*cs9*gfp(p, 1)*gfp(p, 2) - (gfp(p, 1)*gfp(p, 1)*gfp(p, &
                     1))/cs1)))
                  ml(p, 1) = ml(p, 1) + (cs6*lam0(p, 4))
                  ml(p, 2) = ml(p, 2) + (cs6*lam1(p, 1, 4))
                  ml(p, 3) = ml(p, 3) + (cs12*lam1(p, 1, 4))
                  ml(p, 4) = ml(p, 4) + (cs6*lam1(p, 2, 4))
                  ml(p, 5) = ml(p, 5) + (cs12*lam1(p, 2, 4))
                  ml(p, 6) = ml(p, 6) + (cs6*lam1(p, 3, 4))
                  ml(p, 7) = ml(p, 7) + (cs12*lam1(p, 3, 4))
                  ml(p, 8) = ml(p, 8) + (cs6*lam2(p, 1, 4))
                  ml(p, 9) = ml(p, 9) + (cs12*lam2(p, 1, 4))
                  ml(p, 10) = ml(p, 10) + (cs13*lam2(p, 1, 4))
                  ml(p, 11) = ml(p, 11) + (cs6*lam2(p, 2, 4))
                  ml(p, 12) = ml(p, 12) + (cs12*lam2(p, 2, 4))
                  ml(p, 13) = ml(p, 13) + (cs13*lam2(p, 2, 4))
                  ml(p, 14) = ml(p, 14) + (cs6*lam2(p, 4, 4))
                  ml(p, 15) = ml(p, 15) + (cs12*lam2(p, 4, 4))
                  ml(p, 16) = ml(p, 16) + (cs13*lam2(p, 4, 4))
                  ml(p, 17) = ml(p, 17) + (cs6*lam2(p, 3, 4))
                  ml(p, 18) = ml(p, 18) + (cs12*lam2(p, 3, 4))
                  ml(p, 19) = ml(p, 19) + (cs13*lam2(p, 3, 4))
                  ml(p, 20) = ml(p, 20) + (cs6*lam2(p, 5, 4))
                  ml(p, 21) = ml(p, 21) + (cs12*lam2(p, 5, 4))
                  ml(p, 22) = ml(p, 22) + (cs13*lam2(p, 5, 4))
                  ml(p, 23) = ml(p, 23) + (cs6*lam2(p, 6, 4))
                  ml(p, 24) = ml(p, 24) + (cs12*lam2(p, 6, 4))
                  ml(p, 25) = ml(p, 25) + (cs13*lam2(p, 6, 4))
               end do
            end if
         end if

         ! Geometry contraction, shared by all kinds
         do p = 1, np
            dx = px(p) - cx
            dy = py(p) - cy
            dz = pz(p) - cz
            ix = cache_inv_x(p, a)
            cs0 = ml(p, 1)*ix
            cs1 = (ix*ix)
            cs2 = cs1*dy
            cs3 = cs2*dx
            cs4 = cs1*dx*dz
            cs5 = (dx*dx)
            cs6 = (dx*dx*dx)
            cs7 = (ix*ix*ix)
            cs8 = cs7*dy
            cs9 = cs8*dx*dz
            cs10 = cs5*cs7
            cs11 = cs10*dy
            cs12 = cs10*dz
            cs13 = (dy*dy)
            cs14 = cs7*dx
            cs15 = cs13*cs14
            cs16 = (dz*dz)
            cs17 = ml(p, 25)*cs16
            cs18 = (ix*ix*ix*ix*ix)
            cs19 = 3.0_wp*dx
            cs20 = cs18*cs19*dy*dz
            cs21 = (ix*ix*ix*ix)
            cs22 = -ix
            cs23 = 3.0_wp*cs6
            cs24 = -cs1*dy
            cs25 = 3.0_wp*cs5
            cs26 = cs25*dy
            cs27 = -cs21*cs26 - cs24
            cs28 = -cs1*dz
            cs29 = cs25*dz
            cs30 = -cs21*cs29 - cs28
            cs31 = -cs1*dx
            cs32 = cs13*cs19
            cs33 = -cs21*cs32 - cs31
            cs34 = cs16*cs19
            cs35 = -cs21*cs34 - cs31
            cs36 = -cs8
            cs37 = cs18*cs26 + cs36
            cs38 = cs7*dz
            cs39 = -cs38
            cs40 = cs18*cs29 + cs39
            cs41 = -cs14
            cs42 = cs18*cs32 + cs41
            cs43 = cs18*cs34 + cs41
            cs44 = cs2*dz
            cs45 = (dy*dy*dy)
            cs46 = cs13*cs38
            cs47 = 3.0_wp*cs45
            cs48 = cs13*dz
            cs49 = 3.0_wp*cs21
            cs50 = -cs28 - cs48*cs49
            cs51 = cs16*dy
            cs52 = -cs24 - cs49*cs51
            cs53 = 3.0_wp*cs18
            cs54 = cs39 + cs48*cs53
            cs55 = cs36 + cs51*cs53
            cs56 = (dz*dz*dz)
            cs57 = 3.0_wp*cs56
            r1(p) = &
               -ml(p, 2)*(-cs10 - cs22) - ml(p, 3)*cs1*cs5 + ml(p, 4)*cs7*dx*dy - ml(p, &
               5)*cs3 + ml(p, 6)*cs7*dx*dz - ml(p, 7)*cs4 - ml(p, 8)*(-3.0_wp*cs14 + &
               cs18*cs23) - ml(p, 9)*(3.0_wp*cs1*dx - cs21*cs23) - ml(p, 10)*cs6*cs7 - &
               ml(p, 11)*cs37 - ml(p, 12)*cs27 - ml(p, 13)*cs11 - ml(p, 14)*cs40 - ml(p, &
               15)*cs30 - ml(p, 16)*cs12 - ml(p, 17)*cs42 - ml(p, 18)*cs33 - ml(p, &
               19)*cs15 - ml(p, 20)*cs20 + 3.0_wp*ml(p, 21)*cs21*dx*dy*dz - ml(p, &
               22)*cs9 - ml(p, 23)*cs43 - ml(p, 24)*cs35 - cs0*dx - cs14*cs17
            r2(p) = &
               ml(p, 2)*cs7*dx*dy - ml(p, 3)*cs3 - ml(p, 4)*(-cs13*cs7 - cs22) - ml(p, &
               5)*cs1*cs13 + ml(p, 6)*cs7*dy*dz - ml(p, 7)*cs44 - ml(p, 8)*cs37 - ml(p, &
               9)*cs27 - ml(p, 10)*cs11 - ml(p, 11)*cs42 - ml(p, 12)*cs33 - ml(p, &
               13)*cs15 - ml(p, 14)*cs20 + 3.0_wp*ml(p, 15)*cs21*dx*dy*dz - ml(p, &
               16)*cs9 - ml(p, 17)*(cs18*cs47 - 3.0_wp*cs8) - ml(p, 18)*(3.0_wp*cs1*dy - &
               cs21*cs47) - ml(p, 19)*cs45*cs7 - ml(p, 20)*cs54 - ml(p, 21)*cs50 - ml(p, &
               22)*cs46 - ml(p, 23)*cs55 - ml(p, 24)*cs52 - cs0*dy - cs17*cs8
            r3(p) = &
               ml(p, 2)*cs7*dx*dz - ml(p, 3)*cs4 + ml(p, 4)*cs7*dy*dz - ml(p, 5)*cs44 - &
               ml(p, 6)*(-cs16*cs7 - cs22) - ml(p, 7)*cs1*cs16 - ml(p, 8)*cs40 - ml(p, &
               9)*cs30 - ml(p, 10)*cs12 - ml(p, 11)*cs20 + 3.0_wp*ml(p, &
               12)*cs21*dx*dy*dz - ml(p, 13)*cs9 - ml(p, 14)*cs43 - ml(p, 15)*cs35 - &
               ml(p, 16)*cs14*cs16 - ml(p, 17)*cs54 - ml(p, 18)*cs50 - ml(p, 19)*cs46 - &
               ml(p, 20)*cs55 - ml(p, 21)*cs52 - ml(p, 22)*cs16*cs8 - ml(p, &
               23)*(cs18*cs57 - 3.0_wp*cs38) - ml(p, 24)*(3.0_wp*cs1*dz - cs21*cs57) - &
               ml(p, 25)*cs56*cs7 - cs0*dz
         end do
         do p = 1, np
            res(1, a, p) = r1(p)
            res(2, a, p) = r2(p)
            res(3, a, p) = r3(p)
         end do
      end do

   end subroutine svdw_strip_vjp

end submodule moist_cavity_drop_lsf_svdw_kernel_strip
